src/storage/contracts.ts:
/**
 * The storage port surface: what a store accepts, what it returns, and the typed results it uses.
 *
 * Every field name here is a frozen `SCHEMAS.md` name — this file renames nothing. Business
 * outcomes are `StoreResult`s built from the one `ErrorEnvelope` in `src/protocol`; the store never
 * throws for a reachable input and never invents a second error shape.
 *
 * On types: `Decoded<K>` from `src/protocol` derives wire types mechanically from the frozen field
 * table, and two of its consequences matter here. Ids and digests are decoded as plain strings (the
 * brands are compile-time-only on the raw `Id`/`Digest` aliases), and a nested object that is
 * referenced by `$ref` is widened by the `Wire` mapping, so the fields a consumer actually reads are
 * re-narrowed below. Nothing is re-declared: each narrowing points at the same frozen definition.
 *
 * Boundary: the store consumes values that `src/protocol`'s codec has already decoded — the port
 * signatures take `Decoded<K>` — with two deliberate exceptions it decodes itself:
 * `CreateSessionInput.protocol` (a real boundary input) and the `ArtifactRef`s passed to the artifact
 * store. Apart from those, the store does not re-decode transaction content (the protocol layer
 * documents that callers decode once and then trust the result); what it verifies at its own
 * persistence boundary is identity, protocol version, `ArtifactRef` schema/digest binding, and
 * journal continuity — not the schema shape of events, effects or receipts. Effect and receipt
 * content is additionally version-gated against the session's pinned protocol; the closed
 * `Event.type` enum is therefore a caller obligation, not a store-side decode.
 *
 * Two store-internal concepts have no wire object on purpose (`SCHEMAS.md` §3): the dispatch claim
 * and the idempotency request index. Their whole lifetime is inside one `EventStore` CAS
 * transaction; only their ids cross a boundary.
 */
import { fail } from '../protocol/index.js';
import type { Decoded, ErrorCode, ErrorEnvelope } from '../protocol/index.js';

/** A committed journal event. */
export type Event = Omit<Decoded<'Event'>, 'payload'> & { readonly payload: EventPayload };
/** An event a caller submits to `append`. `sequence`/`revision` are assigned by the journal, never by a caller. */
export type EventDraft = Omit<Event, 'sequence' | 'revision'>;
/** The typed event payload, with its `$ref` members re-narrowed. */
export type EventPayload = Omit<Decoded<'EventPayload'>, 'binding' | 'objectRef'> & {
  readonly binding: Binding | null;
  readonly objectRef: ArtifactRef | null;
};
/** The attempt binding every effect and receipt carries. */
export type Binding = Decoded<'Binding'>;
/** A committed effect intention. */
export type Effect = Omit<Decoded<'Effect'>, 'binding' | 'leases' | 'inputRefs' | 'payload'> & {
  readonly binding: Binding;
  readonly leases: readonly Decoded<'LeaseRef'>[];
  readonly inputRefs: readonly ArtifactRef[];
  readonly payload: Decoded<'EffectPayload'>;
};
/** An execution receipt. */
export type Receipt = Omit<Decoded<'Receipt'>, 'binding' | 'artifactRefs' | 'usage'> & {
  readonly binding: Binding;
  readonly artifactRefs: readonly ArtifactRef[];
  readonly usage: readonly Decoded<'Usage'>[];
};
/** An immutable artifact reference. */
export type ArtifactRef = Decoded<'ArtifactRef'>;
/** A journal-derived node state entry. */
export type NodeStateEntry = Decoded<'NodeStateEntry'>;
/** The runtime protocol envelope. */
export type ProtocolEnvelope = Decoded<'ProtocolVersion'>;
/** Session dispatch mode, derived from session events. */
export type DispatchMode = 'active' | 'paused' | 'cancelling' | 'cancelled';

export type StoreOk<T> = { readonly ok: true; readonly value: T };
export type StoreErr = { readonly ok: false; readonly error: ErrorEnvelope };
export type StoreResult<T> = StoreOk<T> | StoreErr;

export function storeOk<T>(value: T): StoreOk<T> {
  return { ok: true, value };
}

export function storeFail(code: ErrorCode, message: string, refs: readonly string[] = []): StoreErr {
  return { ok: false, error: fail(code, message, refs) };
}

// --- EventStore -------------------------------------------------------------------------------

export interface CreateSessionInput {
  readonly sessionId: string;
  readonly epoch: number;
  /** Boundary input (argv/YAML/host): the protocol envelope is decoded and version-gated here. */
  readonly protocol: unknown;
}

export interface SessionHandle {
  readonly sessionId: string;
  readonly epoch: number;
  readonly schemaVersion: string;
}

export interface AppendRequest {
  readonly sessionId: string;
  /** Caller identity for idempotent submission: same id + same content is a replay, not a second commit. */
  readonly requestId: string;
  readonly expectedRevision: number;
  readonly epoch: number;
  readonly events: readonly EventDraft[];
  readonly effects: readonly Effect[];
  readonly receipts: readonly Receipt[];
}

export interface AppendOutcome {
  readonly disposition: 'committed' | 'duplicate';
  readonly sessionId: string;
  readonly revision: number;
  readonly eventIds: readonly string[];
  readonly effectIds: readonly string[];
}

export interface ReplayState {
  readonly sessionId: string;
  readonly revision: number;
  readonly epoch: number;
  readonly lastSequence: number | null;
  readonly dispatchMode: DispatchMode;
  readonly nodeStates: readonly NodeStateEntry[];
}

export interface JournalProjection extends ReplayState {
  /** Effects committed, unclaimed and dispatchable at the current epoch. Safe to send. */
  readonly pendingEffectIds: readonly string[];
  /** Effects claimed (or reported unknown) whose actual outcome must be reconciled, never resent. */
  readonly unknownEffectIds: readonly string[];
  /**
   * Effects intended at an earlier epoch. Their lease is stale, so they are not dispatchable until
   * they are re-authorized under the current epoch; they are surfaced rather than silently dropped.
   */
  readonly staleEffectIds: readonly string[];
}

export interface OutboxEntryProjection {
  readonly effectId: string;
  readonly state: 'intended' | 'dispatched' | 'unknown' | 'resolved';
  readonly resolvedStatus: Receipt['status'] | null;
}

export interface OutboxProjection {
  readonly entries: readonly OutboxEntryProjection[];
  /** Stale receipts kept as evidence without touching the current attempt. */
  readonly archivedReceiptIds: readonly string[];
}

export interface DispatchClaim {
  readonly claimId: string;
  readonly epoch: number;
  readonly fencingToken: number;
}

export interface DispatchInput {
  readonly expectedRevision: number;
  readonly epoch: number;
  readonly effectId: string;
  readonly claimId: string;
}

export interface ReceiptInput {
  readonly expectedRevision: number;
  readonly epoch: number;
  readonly receipt: Receipt;
  /** The committed artifact that carries the receipt content; its id is the receipt id. */
  readonly objectRef: ArtifactRef;
}

export interface ReceiptOutcome {
  readonly disposition: 'applied' | 'duplicate' | 'archived';
  readonly revision: number;
  readonly effectId: string;
  readonly receiptId: string;
}

export interface ExportedSession {
  readonly sessionId: string;
  readonly epoch: number;
  readonly protocol: ProtocolEnvelope;
  readonly revision: number;
  readonly events: readonly Event[];
  readonly effects: readonly Effect[];
  readonly receipts: readonly Receipt[];
}

export interface EventStore {
  createSession(input: CreateSessionInput): StoreResult<SessionHandle>;
  append(request: AppendRequest): StoreResult<AppendOutcome>;
  exportSession(sessionId: string): StoreResult<ExportedSession>;
  replay(sessionId: string): StoreResult<JournalProjection>;
  outbox(sessionId: string): StoreResult<OutboxProjection>;
  nextEffects(sessionId: string): StoreResult<readonly Effect[]>;
  dispatchEffect(sessionId: string, input: DispatchInput): StoreResult<AppendOutcome>;
  applyReceipt(sessionId: string, input: ReceiptInput): StoreResult<ReceiptOutcome>;
  reconcileEffect(sessionId: string, input: ReceiptInput): StoreResult<ReceiptOutcome>;
}

// --- SnapshotStore ----------------------------------------------------------------------------

export interface SnapshotInput {
  readonly sessionId: string;
  readonly revision: number;
  readonly epoch: number;
  /** Last journal sequence the projection covers. */
  readonly sequence: number;
  readonly schemaVersion: string;
  readonly projection: ReplayState;
}

export interface StoredSnapshot extends SnapshotInput {
  readonly digest: string;
}

export interface Recovery {
  readonly projection: ReplayState;
  readonly usedSnapshot: boolean;
  /** First journal sequence replayed (0, or `snapshot.sequence + 1` when a snapshot was used). */
  readonly replayedFrom: number;
}

export interface SnapshotStore {
  /** `save` stores a projection verbatim and version-gates it; `recover` is what checks it against the journal. */
  save(input: SnapshotInput): StoreResult<StoredSnapshot>;
  load(sessionId: string): StoreResult<StoredSnapshot | null>;
  recover(sessionId: string, events: readonly Event[]): StoreResult<Recovery>;
}

// --- ArtifactStore ----------------------------------------------------------------------------

export interface ArtifactStore {
  put(ref: ArtifactRef, bytes: string): StoreResult<{ readonly disposition: 'stored' | 'duplicate' }>;
  get(ref: ArtifactRef): StoreResult<string>;
  ids(): readonly string[];
}

src/storage/identity.ts:
/**
 * Deterministic object identity for the storage layer.
 *
 * The store answers "is this the same command/effect/receipt/event?" with a content digest. The
 * digest input is the object's canonical serialization: object keys sorted, arrays in order, no
 * whitespace. Insertion order therefore cannot change an identity, which is the one property the
 * frozen `SCHEMAS.md` S22 makes load-bearing for idempotency.
 *
 * The digest itself is an injected port (I07): this module never imports `node:crypto` and never
 * picks a hash, so a memory store and a durable store can be compared byte-for-byte on the same
 * input, and a test can swap in a deterministic stub.
 */
/** Produces a content digest for exact input bytes. Injected, never discovered. */
export interface DigestPort {
  digest(bytes: string): string;
}

/** Stable rendering of a JSON-shaped value: keys sorted, arrays ordered, no whitespace. */
export function canonical(value: unknown): string {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'string' || typeof value === 'boolean') return JSON.stringify(value);
  if (typeof value === 'number') return String(value);
  if (Array.isArray(value)) return `[${value.map((item) => canonical(item)).join(',')}]`;
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    const fields = Object.keys(record)
      .filter((key) => record[key] !== undefined)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonical(record[key])}`);
    return `{${fields.join(',')}}`;
  }
  return JSON.stringify(String(value));
}

/** The content identity of `value` under the injected digest port. */
export function identityDigest(port: DigestPort, value: unknown): string {
  return port.digest(canonical(value));
}

src/storage/projection.ts:
/**
 * The journal reducer: `replay(events)` rebuilds the derived read state from events alone.
 *
 * It is a pure function of its inputs — no clock, no host call, no write — which is what makes
 * "replay only rebuilds state" true by construction (`CONTRACTS.md` §5.10, S25). The reducer is the
 * authority on three things the journal must never fake:
 *
 *   - **continuity**: `sequence` starts at 0 and increments by one; a hole is a recovery gap and is
 *     refused (`EFK_RECOVERY_SEQUENCE_GAP`) rather than patched from a cached projection;
 *   - **transaction shape**: `revision` is monotone and steps by one per transaction;
 *   - **transition chaining**: a `node.transition`'s `before` must equal the previous `after` for
 *     the same `(nodeId, attemptOrdinal)`.
 *
 * `verifyProjection` is the anti-fake-recovery check: it recomputes and compares, so a snapshot that
 * merely claims a state cannot be used as if it had been recovered.
 */
import type { Event, NodeStateEntry, ReplayState, StoreResult } from './contracts.js';
import { storeFail, storeOk } from './contracts.js';
import { canonical } from './identity.js';

function stateKey(nodeId: string, attemptOrdinal: number): string {
  return `${nodeId}#${attemptOrdinal}`;
}

/** The derived state of a session with no committed events yet. */
export function emptyReplayState(sessionId: string, epoch: number): ReplayState {
  return { sessionId, revision: 0, epoch, lastSequence: null, dispatchMode: 'active', nodeStates: [] };
}

function compareState(a: NodeStateEntry, b: NodeStateEntry): number {
  if (a.nodeId !== b.nodeId) return a.nodeId < b.nodeId ? -1 : 1;
  return a.attemptOrdinal - b.attemptOrdinal;
}

function dispatchModeFor(event: Event, current: ReplayState['dispatchMode']): ReplayState['dispatchMode'] {
  switch (event.type) {
    case 'session.paused':
      return 'paused';
    case 'session.resumed':
      return 'active';
    case 'session.cancel-requested':
      return 'cancelling';
    case 'session.cancel-confirmed':
      return 'cancelled';
    default:
      return current;
  }
}

/**
 * Rebuild the derived state from `events`, optionally continuing from a verified `seed` (a snapshot
 * prefix). Only `events` after the seed may be passed; the seed's `lastSequence` is the continuity
 * anchor.
 */
export function replay(events: readonly Event[], seed?: ReplayState): StoreResult<ReplayState> {
  const first = events[0];
  const sessionId = seed?.sessionId ?? first?.sessionId;
  if (sessionId === undefined) {
    return storeFail('EFK_SCHEMA_INVALID', 'cannot replay an empty journal without a seed');
  }

  let revision = seed?.revision ?? 0;
  const baseline = first?.type === 'session.epoch-changed' ? first.epoch - 1 : first?.epoch;
  let epoch = seed?.epoch ?? baseline ?? 1;
  let lastSequence = seed?.lastSequence ?? -1;
  let dispatchMode: ReplayState['dispatchMode'] = seed?.dispatchMode ?? 'active';

  const states = new Map<string, NodeStateEntry>();
  if (seed !== undefined) {
    for (const entry of seed.nodeStates) states.set(stateKey(entry.nodeId, entry.attemptOrdinal), entry);
  }

  for (const event of events) {
    if (event.sessionId !== sessionId) {
      return storeFail('EFK_INVARIANT_VIOLATION', `event ${event.eventId} belongs to session ${event.sessionId}, not ${sessionId}`);
    }
    if (event.sequence !== lastSequence + 1) {
      return storeFail('EFK_RECOVERY_SEQUENCE_GAP', `journal expected sequence ${lastSequence + 1} but found ${event.sequence} at ${event.eventId}`, [sessionId]);
    }
    if (event.revision !== revision && event.revision !== revision + 1) {
      return storeFail('EFK_INVARIANT_VIOLATION', `event ${event.eventId} carries revision ${event.revision}, which is not ${revision} or ${revision + 1}`);
    }
    revision = event.revision;
    lastSequence = event.sequence;

    if (event.type === 'session.epoch-changed') {
      if (event.epoch <= epoch) {
        return storeFail('EFK_INVARIANT_VIOLATION', `session.epoch-changed ${event.eventId} moves epoch ${epoch} -> ${event.epoch}`);
      }
      epoch = event.epoch;
    } else if (event.epoch !== epoch) {
      return storeFail('EFK_INVARIANT_VIOLATION', `event ${event.eventId} carries epoch ${event.epoch} outside session epoch ${epoch}`);
    }

    if (event.type === 'node.transition') {
      const { binding, before, after } = event.payload;
      if (binding === null || after === null) {
        return storeFail('EFK_SCHEMA_INVALID', `node.transition ${event.eventId} requires a binding and an after state`);
      }
      const key = stateKey(binding.nodeId, binding.attemptOrdinal);
      const previous = states.get(key);
      if (previous !== undefined && before !== previous.state) {
        return storeFail('EFK_INVARIANT_VIOLATION', `transition ${event.eventId} claims before=${before} but ${key} is ${previous.state}`);
      }
      states.set(key, {
        nodeId: binding.nodeId,
        attemptOrdinal: binding.attemptOrdinal,
        epoch: event.epoch,
        state: after,
        sinceSequence: event.sequence,
      });
    }

    dispatchMode = dispatchModeFor(event, dispatchMode);
  }

  return storeOk({
    sessionId,
    revision,
    epoch,
    lastSequence: lastSequence === -1 ? null : lastSequence,
    dispatchMode,
    nodeStates: [...states.values()].sort(compareState),
  });
}

/**
 * Refuse a projection that does not match what the journal actually says. This is the check that
 * makes a cached snapshot unusable as a shortcut around a gap or a diverged history.
 */
export function verifyProjection(claimed: ReplayState, events: readonly Event[]): StoreResult<ReplayState> {
  const replayed = replay(events);
  if (!replayed.ok) return replayed;
  if (canonical(replayed.value) !== canonical(claimed)) {
    return storeFail('EFK_INVARIANT_VIOLATION', `cached projection for ${claimed.sessionId} does not match the journal`, [claimed.sessionId]);
  }
  return replayed;
}

src/storage/outbox.ts:
/**
 * The outbox as a pure projection of the journal.
 *
 * There is no second mutable outbox index that could drift from the journal. The delivery state of
 * every effect is re-derived from the committed events:
 *
 *   - `effect.intended`   -> the effect is `intended` and safe to send;
 *   - `effect.dispatched` -> it was claimed before the host call, so its outcome is now unknown
 *     until a receipt lands; it must never be sent again;
 *   - `receipt.applied`   -> resolved, or still `unknown` if the receipt itself says so;
 *   - `receipt.archived`  -> a stale receipt kept as evidence; it does not move the effect.
 *
 * That is exactly invariant 4/5/6: the intention and the claim are the same journal as the events,
 * a replayed journal reproduces the outbox, and an unknown effect is visible for reconciliation
 * instead of being retried.
 */
import type { Effect, Event, OutboxEntryProjection, OutboxProjection, Receipt, StoreResult } from './contracts.js';
import { storeFail, storeOk } from './contracts.js';

/** Derive the outbox from the journal plus the committed effect/receipt content it references. */
export function projectOutbox(
  events: readonly Event[],
  effects: ReadonlyMap<string, Effect>,
  receipts: ReadonlyMap<string, Receipt>,
): StoreResult<OutboxProjection> {
  const order: string[] = [];
  const entries = new Map<string, OutboxEntryProjection>();
  const archivedReceiptIds: string[] = [];

  for (const event of events) {
    switch (event.type) {
      case 'effect.intended': {
        const effectId = event.payload.effectId;
        if (effectId === null) {
          return storeFail('EFK_SCHEMA_INVALID', `effect.intended ${event.eventId} carries no effectId`);
        }
        if (entries.has(effectId)) {
          return storeFail('EFK_INVARIANT_VIOLATION', `effect ${effectId} is intended twice in the journal`, [effectId]);
        }
        if (!effects.has(effectId)) {
          return storeFail('EFK_ARTIFACT_UNAVAILABLE', `effect ${effectId} content is referenced by ${event.eventId} but not committed`, [effectId]);
        }
        order.push(effectId);
        entries.set(effectId, { effectId, state: 'intended', resolvedStatus: null });
        break;
      }
      case 'effect.dispatched': {
        const effectId = event.payload.effectId;
        if (effectId === null) {
          return storeFail('EFK_SCHEMA_INVALID', `effect.dispatched ${event.eventId} carries no effectId`);
        }
        const current = entries.get(effectId);
        if (current === undefined) {
          return storeFail('EFK_INVARIANT_VIOLATION', `effect ${effectId} was dispatched without a committed intention`, [effectId]);
        }
        if (current.state !== 'intended') {
          return storeFail('EFK_INVARIANT_VIOLATION', `effect ${effectId} was dispatched while ${current.state}`, [effectId]);
        }
        entries.set(effectId, { effectId, state: 'dispatched', resolvedStatus: null });
        break;
      }
      case 'receipt.applied': {
        const { effectId, objectRef } = event.payload;
        if (effectId === null || objectRef === null) {
          return storeFail('EFK_SCHEMA_INVALID', `receipt.applied ${event.eventId} requires an effectId and an objectRef`);
        }
        if (!entries.has(effectId)) {
          return storeFail('EFK_INVARIANT_VIOLATION', `receipt for unknown effect ${effectId} in ${event.eventId}`, [effectId]);
        }
        const receipt = receipts.get(objectRef.id);
        if (receipt === undefined) {
          return storeFail('EFK_ARTIFACT_UNAVAILABLE', `receipt ${objectRef.id} content is referenced by ${event.eventId} but not committed`, [objectRef.id]);
        }
        entries.set(effectId, {
          effectId,
          state: receipt.status === 'unknown' ? 'unknown' : 'resolved',
          resolvedStatus: receipt.status === 'unknown' ? null : receipt.status,
        });
        break;
      }
      case 'receipt.archived': {
        const { objectRef } = event.payload;
        if (objectRef === null) {
          return storeFail('EFK_SCHEMA_INVALID', `receipt.archived ${event.eventId} requires an objectRef`);
        }
        archivedReceiptIds.push(objectRef.id);
        break;
      }
      default:
        break;
    }
  }

  return storeOk({ entries: order.map((effectId) => entries.get(effectId) as OutboxEntryProjection), archivedReceiptIds });
}

/** Effects committed but not yet claimed; the only set a dispatcher may send. */
export function intendedIds(projection: OutboxProjection): readonly string[] {
  return projection.entries.filter((entry) => entry.state === 'intended').map((entry) => entry.effectId);
}

/** Effects whose actual outcome is unknown (claimed, or reported unknown); they require reconcile. */
export function reconcileIds(projection: OutboxProjection): readonly string[] {
  return projection.entries.filter((entry) => entry.state === 'dispatched' || entry.state === 'unknown').map((entry) => entry.effectId);
}

src/storage/artifacts/access.ts:
/**
 * cp2 — access partition. Two independent axes decide whether a reference may be read.
 *
 * `SCHEMAS.md` states the axes are separate: "来源分区不由 visibility 推断". A13 adds that an
 * executor's read path must not contain a `final`/`held-out` artifact reference at all, and
 * `PrivacyPolicy` fixes `privateTests` to `evaluator-only`. So both `visibility` and `partition`
 * gate a read, and the only role allowed past `internal` is `evaluator`.
 *
 * The withheld side of a partition deliberately carries counts and reasons, never ids, locators or
 * digests: A13 forbids the executor-visible path from containing the reference, and an id is part of
 * the reference. A caller that needs to audit *what* was withheld asks as the `evaluator` audience,
 * which withholds no valid reference. Public classification and report entry points decode each
 * reference with the frozen codec before looking up either axis; malformed enums fail typed.
 */
import { decode } from '../../protocol/index.js';
import { storeOk } from '../index.js';
import type { StoreResult } from '../index.js';
import type { ArtifactRef, Audience, FeedbackPartition, Visibility } from './types.js';

/** Increasing sensitivity. Used only to compare against an audience ceiling. */
const VISIBILITY_RANK: Readonly<Record<Visibility, number>> = {
  public: 0,
  internal: 1,
  private: 2,
  'held-out': 3,
  final: 4,
};

/**
 * The information ceiling per audience. `author` is the executing agent, `report` the default
 * report/feedback view, `asset-staging` the asset writer; all three stop at `internal`. `evaluator`
 * is the sole audience whose job is private tests and held-out/final data.
 */
const AUDIENCE_CEILING: Readonly<Record<Audience, Visibility>> = {
  author: 'internal',
  evaluator: 'final',
  report: 'internal',
  'asset-staging': 'internal',
};

/** Whether an audience may read artifacts from `held-out`/`final` source partitions at all. */
const AUDIENCE_SEES_RESTRICTED_PARTITION: Readonly<Record<Audience, boolean>> = {
  author: false,
  evaluator: true,
  report: false,
  'asset-staging': false,
};

/** Source partitions that never become author-visible feedback or asset material. */
const RESTRICTED_PARTITION: Readonly<Record<ArtifactRef['partition'], boolean>> = {
  train: false,
  dev: false,
  'held-out': true,
  final: true,
  'not-evaluation': false,
};

export function visibilityCeiling(audience: Audience): Visibility {
  return AUDIENCE_CEILING[audience];
}

export function isRestrictedPartition(ref: ArtifactRef): StoreResult<boolean> {
  const decoded = decode('ArtifactRef', ref);
  if (!decoded.ok) return decoded;
  return storeOk(RESTRICTED_PARTITION[ref.partition]);
}

/** Why a reference is withheld from `audience`; `'none'` means it may be read. */
export function withheldReason(ref: ArtifactRef, audience: Audience): StoreResult<'none' | 'visibility' | 'partition'> {
  const decoded = decode('ArtifactRef', ref);
  if (!decoded.ok) return decoded;
  if (VISIBILITY_RANK[ref.visibility] > VISIBILITY_RANK[AUDIENCE_CEILING[audience]]) return storeOk('visibility');
  if (!AUDIENCE_SEES_RESTRICTED_PARTITION[audience] && RESTRICTED_PARTITION[ref.partition]) return storeOk('partition');
  return storeOk('none');
}

/** Split a reference set into the part `audience` may read and a count of what it may not. */
export function partitionFeedback(refs: readonly ArtifactRef[], audience: Audience): StoreResult<FeedbackPartition> {
  const visible: ArtifactRef[] = [];
  let withheldVisibility = 0;
  let withheldPartition = 0;
  for (const ref of refs) {
    const reason = withheldReason(ref, audience);
    if (!reason.ok) return reason;
    if (reason.value === 'none') visible.push(ref);
    else if (reason.value === 'visibility') withheldVisibility += 1;
    else withheldPartition += 1;
  }
  return storeOk({ audience, visible, withheldVisibility, withheldPartition });
}

/** The default report view: everything an author-facing report may carry, and nothing else. */
export function defaultReportRefs(refs: readonly ArtifactRef[]): StoreResult<FeedbackPartition> {
  return partitionFeedback(refs, 'report');
}

src/storage/artifacts/admit.ts:
/**
 * cp1 — the writer entry: admit a produced artifact, or refuse to commit it.
 *
 * The order is the contract. Producer attribution and the expected schema version come first, then
 * the attempt binding, and only then the bytes reach the injected `ArtifactStore`. A result computed
 * against an old base, a stale graph revision, or a superseded attempt never reaches the store at
 * all — `EFK_ARTIFACT_BINDING_MISMATCH` is returned before any durable effect exists.
 *
 * Byte-level content identity (bytes vs `ArtifactRef.digest`, immutability of an id, the S01 size
 * bound and credential-in-locator rule) is the store's frozen contract and is not duplicated here:
 * `store.put` owns it, and its refusal propagates unchanged. This lane computes no digest, so no
 * second digest implementation can disagree with the store's.
 */
import { storeOk } from '../index.js';
import type { StoreResult } from '../index.js';
import { checkBinding } from './binding.js';
import { attributeProducer, matchSchema } from './identity.js';
import type { ActorRef, ArtifactExpectation, ArtifactRef, ArtifactStore, Binding } from './types.js';

export interface AdmitRequest {
  /** The reference the producer claims, already through the codec's boundary. */
  readonly ref: ArtifactRef;
  readonly bytes: string;
  /** The attempt that produced it, and the schema version the consumer is entitled to. */
  readonly expectation: ArtifactExpectation;
}

export interface AdmissionReceipt {
  readonly ref: ArtifactRef;
  readonly producer: ActorRef;
  readonly binding: Binding | null;
  readonly disposition: 'stored' | 'duplicate';
}

export function admitArtifact(request: AdmitRequest, store: ArtifactStore): StoreResult<AdmissionReceipt> {
  const producer = attributeProducer(request.ref);
  if (!producer.ok) return producer;

  const schema = matchSchema(request.ref, request.expectation.schema);
  if (!schema.ok) return schema;

  const binding = checkBinding(request.ref, request.expectation);
  if (!binding.ok) return binding;

  const stored = store.put(request.ref, request.bytes);
  if (!stored.ok) return stored;

  return storeOk({
    ref: request.ref,
    producer: producer.value,
    binding: binding.value,
    disposition: stored.value.disposition,
  });
}

src/storage/artifacts/availability.ts:
/**
 * cp2 — the read path: access, expiry, and real bytes.
 *
 * One order decides every read: the audience is checked first (A13 — an executor must not reach
 * `held-out`/`final` content at all), then the reference's own expiry, then any consumer expectation,
 * and finally the injected `ArtifactStore`. The store is the only source of bytes, so a reference
 * whose locator has gone away
 * fails typed as `EFK_ARTIFACT_UNAVAILABLE`; there is no branch that hands back the reference, its
 * digest or a summary instead. `expiresAt` is compared against an injected `Instant`, never a clock
 * read here (I07), and `null` means no expiry.
 */
import { storeFail, storeOk } from '../index.js';
import type { StoreResult } from '../index.js';
import { withheldReason } from './access.js';
import { checkBinding } from './binding.js';
import { attributeProducer, matchSchema } from './identity.js';
import type { ArtifactExpectation, ArtifactRef, ArtifactStore, Audience, Instant } from './types.js';

/** A reference is unavailable at or after its expiry; `null` never expires. */
export function checkAvailability(ref: ArtifactRef, at: Instant): StoreResult<ArtifactRef> {
  if (ref.expiresAt !== null && at >= ref.expiresAt) {
    return storeFail('EFK_ARTIFACT_UNAVAILABLE', `artifact ${ref.id} expired at ${ref.expiresAt}`, [ref.id]);
  }
  return storeOk(ref);
}

/**
 * Read one artifact's bytes for one audience. Withheld references are refused before the store is
 * consulted, so a privacy violation cannot be masked by an unavailable locator. If supplied, the
 * consumer's producer/schema/binding checks also precede byte retrieval, after access and expiry.
 */
export function readArtifact(
  ref: ArtifactRef,
  audience: Audience,
  at: Instant,
  store: ArtifactStore,
  expectation?: ArtifactExpectation,
): StoreResult<string> {
  const reason = withheldReason(ref, audience);
  if (!reason.ok) return reason;
  if (reason.value !== 'none') {
    return storeFail(
      'EFK_PRIVACY_VIOLATION',
      `artifact is withheld from the ${audience} audience (${reason.value})`,
    );
  }
  const available = checkAvailability(ref, at);
  if (!available.ok) return available;
  if (expectation !== undefined) {
    const producer = attributeProducer(ref);
    if (!producer.ok) return producer;
    const schema = matchSchema(ref, expectation.schema);
    if (!schema.ok) return schema;
    const binding = checkBinding(ref, expectation);
    if (!binding.ok) return binding;
  }
  return store.get(ref);
}

src/storage/artifacts/binding.ts:
/**
 * cp1 — attempt binding. S09: a node/effect product must carry a complete binding whose graph,
 * session, host session, node, attempt, epoch and base revision match, and a mismatched binding is
 * `EFK_ARTIFACT_BINDING_MISMATCH` with no partial acceptance.
 *
 * The base revision is the load-bearing one for evolution: an artifact produced against a
 * superseded workspace base is refused, because accepting it would let a result computed on old
 * evidence be reported as the result of the current attempt. The graph revision is refused for the
 * same reason — a product of a topology the attempt no longer runs under is not its output.
 *
 * `checkBinding` is one call, not a scattering of comparisons at each consumer: the mismatch list it
 * builds is the single place that decides what "bound to this attempt" means.
 */
import { storeFail, storeOk } from '../index.js';
import type { StoreResult } from '../index.js';
import type { ArtifactExpectation, ArtifactRef, Binding, BindingExpectation } from './types.js';

/** Frozen field names that disagree between a reference and the attempt about to consume it. */
export function bindingMismatches(binding: Binding, expected: BindingExpectation): readonly string[] {
  const mismatched: string[] = [];
  if (binding.sessionId !== expected.sessionId) mismatched.push('sessionId');
  if (binding.hostSessionId !== expected.hostSessionId) mismatched.push('hostSessionId');
  if (binding.graph.graphId !== expected.graph.graphId) mismatched.push('graph.graphId');
  if (binding.graph.revision !== expected.graph.revision) mismatched.push('graph.revision');
  if (binding.graph.digest !== expected.graph.digest) mismatched.push('graph.digest');
  if (binding.nodeId !== expected.nodeId) mismatched.push('nodeId');
  if (binding.attemptId !== expected.attemptId) mismatched.push('attemptId');
  if (binding.attemptOrdinal !== expected.attemptOrdinal) mismatched.push('attemptOrdinal');
  if (binding.epoch !== expected.epoch) mismatched.push('epoch');
  if (binding.baseDigest !== expected.baseDigest) mismatched.push('baseDigest');
  return mismatched;
}

/**
 * Bind `ref` to the attempt the consumer is holding out for.
 *
 * A `pre-source` expectation with `binding: null` asserts nothing and returns the reference's own
 * binding, which may be `null` — that is the frozen allowance for approvals, source pins and
 * protocol snapshots. Every other case must match field for field, including `baseDigest`.
 */
export function checkBinding(ref: ArtifactRef, expected: ArtifactExpectation): StoreResult<Binding | null> {
  const wanted = expected.binding;
  if (wanted === null) return storeOk(ref.binding);
  const binding = ref.binding;
  if (binding === null) {
    return storeFail(
      'EFK_ARTIFACT_BINDING_MISMATCH',
      `${expected.productKind} artifact ${ref.id} carries no attempt binding, expected node ${wanted.nodeId} attempt ${wanted.attemptId}`,
      [ref.id],
    );
  }
  const mismatched = bindingMismatches(binding, wanted);
  if (mismatched.length > 0) {
    return storeFail(
      'EFK_ARTIFACT_BINDING_MISMATCH',
      `artifact ${ref.id} is bound to a different ${mismatched.join('/')} than the consuming attempt`,
      [ref.id],
    );
  }
  return storeOk(binding);
}

src/storage/artifacts/consumer.ts:
/**
 * cp3 — one consumer entry for the three artifact consumers, plus the frozen codes their error paths
 * can return. `workspace`, `evaluator` and `asset` are the consumers named by `INTERFACES.md`; each
 * is a branch of one `verifyForConsumer` call, so no consumer re-implements a check the others skip.
 *
 * Admission returns **bytes**. A consumer never receives a reference, digest or summary in place of
 * content: every admitted entry has been read through the injected `ArtifactStore`.
 *
 * Error matrix (`ARTIFACT_ERROR_MATRIX`) — code → the condition that produces it:
 *
 * | code | condition |
 * |---|---|
 * | `EFK_SCHEMA_INVALID` | malformed references/content at the codec/store boundary, or either empty asset material list (frozen minItems: 1) |
 * | `EFK_ARTIFACT_DIGEST_MISMATCH` | propagated from `ArtifactStore.put` — the bytes do not hash to the reference digest (S01/S22) |
 * | `EFK_ARTIFACT_BINDING_MISMATCH` | producer is an unattributable `human`; declared schema triple ≠ expected version; node product with no binding; session/host session, graph `graphId`/`revision`/`digest`, `nodeId`, `attemptId`, `attemptOrdinal`, `epoch` or `baseDigest` differs from the consuming attempt |
 * | `EFK_ARTIFACT_UNAVAILABLE` | at or after `expiresAt`, or the store cannot resolve the locator — the read never falls back to a summary |
 * | `EFK_PRIVACY_VIOLATION` | the audience ceiling (A13: executor/`author`/`report`/`asset-staging` stop at `internal`) is exceeded, or a `held-out`/`final` partition is read by an audience that may not see restricted partitions |
 * | `EFK_EVALUATION_PROTOCOL_MISMATCH` | asset material: a `contentRef` comes from `held-out`/`final`, or a `sourceTrace` is not from `train` (S18) |
 * | `EFK_ASSET_QUALIFICATION_INVALID` | asset material: a dependency of the qualification was revoked (S17) |
 */
import { storeFail, storeOk } from '../index.js';
import type { StoreResult } from '../index.js';
import { decode } from '../../protocol/index.js';
import type { ErrorCode } from '../../protocol/index.js';
import { isRestrictedPartition } from './access.js';
import { readArtifact } from './availability.js';
import type {
  AdmittedArtifact,
  ArtifactExpectation,
  ArtifactRef,
  ArtifactStore,
  Audience,
  ConsumerAdmission,
  ConsumerRequest,
  ConsumerRole,
} from './types.js';

/** The audience each consumer reads as. `workspace` is the executing agent (A13's executor). */
const CONSUMER_AUDIENCE: Readonly<Record<ConsumerRole, Audience>> = {
  workspace: 'author',
  evaluator: 'evaluator',
  asset: 'asset-staging',
};

export const ARTIFACT_ERROR_MATRIX: Readonly<Partial<Record<ErrorCode, string>>> = {
  EFK_SCHEMA_INVALID: 'malformed reference/content at the codec/store boundary, or an empty contentRefs/sourceTraces list',
  EFK_ARTIFACT_DIGEST_MISMATCH: 'propagated from ArtifactStore.put: bytes do not hash to the reference digest',
  EFK_ARTIFACT_BINDING_MISMATCH: 'unattributable producer, schema version mismatch, missing binding, or any session/host-session/graph/node/attempt/epoch/base field differs',
  EFK_ARTIFACT_UNAVAILABLE: 'at or after expiresAt, or the store cannot resolve the locator; a summary never substitutes',
  EFK_PRIVACY_VIOLATION: 'audience ceiling exceeded, or a held-out/final partition read by an audience that may not see it',
  EFK_EVALUATION_PROTOCOL_MISMATCH: 'asset material from a non-train source trace or a held-out/final content reference',
  EFK_ASSET_QUALIFICATION_INVALID: 'asset qualification invalidated by a revoked dependency',
};

function consumerAudience(role: ConsumerRole): Audience {
  return CONSUMER_AUDIENCE[role];
}

function admitBoundRef(
  role: 'workspace' | 'evaluator',
  ref: ArtifactRef,
  expectation: ArtifactExpectation,
  at: number,
  store: ArtifactStore,
): StoreResult<AdmittedArtifact> {
  const bytes = readArtifact(ref, consumerAudience(role), at, store, expectation);
  if (!bytes.ok) return bytes;

  return storeOk({ ref, bytes: bytes.value });
}

function admitBoundRefs(
  role: 'workspace' | 'evaluator',
  request: Extract<ConsumerRequest, { role: 'workspace' | 'evaluator' }>,
  store: ArtifactStore,
): StoreResult<ConsumerAdmission> {
  const evidence: AdmittedArtifact[] = [];
  for (const ref of request.refs) {
    const admitted = admitBoundRef(role, ref, request.expectation, request.at, store);
    if (!admitted.ok) return admitted;
    evidence.push(admitted.value);
  }
  return storeOk({ role, audience: consumerAudience(role), evidence });
}

/** Asset refusals are agent-visible too; withheld material must not be named in either field. */
function protocolMismatch(what: string): ReturnType<typeof storeFail> {
  return storeFail('EFK_EVALUATION_PROTOCOL_MISMATCH', `artifact ${what}`);
}

function admitAssetMaterial(
  request: Extract<ConsumerRequest, { role: 'asset' }>,
  store: ArtifactStore,
): StoreResult<ConsumerAdmission> {
  if (request.revokedDependencies.length > 0) {
    return storeFail(
      'EFK_ASSET_QUALIFICATION_INVALID',
      'asset qualification is invalidated by revoked dependencies',
      request.revokedDependencies,
    );
  }
  if (request.contentRefs.length === 0 || request.sourceTraces.length === 0) {
    return storeFail('EFK_SCHEMA_INVALID', 'asset contentRefs and sourceTraces must each contain at least one reference');
  }
  const audience = consumerAudience('asset');
  const evidence: AdmittedArtifact[] = [];

  for (const ref of request.contentRefs) {
    const restricted = isRestrictedPartition(ref);
    if (!restricted.ok) return restricted;
    if (restricted.value) {
      return protocolMismatch(`comes from the ${ref.partition} partition, which never becomes asset content`);
    }
    const bytes = readArtifact(ref, audience, request.at, store);
    if (!bytes.ok) return bytes;
    evidence.push({ ref, bytes: bytes.value });
  }

  for (const ref of request.sourceTraces) {
    const decoded = decode('ArtifactRef', ref);
    if (!decoded.ok) return decoded;
    if (ref.partition !== 'train') {
      return protocolMismatch(`is a source trace from the ${ref.partition} partition; asset source traces are train-only`);
    }
    const bytes = readArtifact(ref, audience, request.at, store);
    if (!bytes.ok) return bytes;
    evidence.push({ ref, bytes: bytes.value });
  }

  return storeOk({ role: 'asset', audience, evidence });
}

/** The single verification entry for workspace, evaluator and asset consumers. */
export function verifyForConsumer(request: ConsumerRequest, store: ArtifactStore): StoreResult<ConsumerAdmission> {
  switch (request.role) {
    case 'workspace':
    case 'evaluator':
      return admitBoundRefs(request.role, request, store);
    case 'asset':
      return admitAssetMaterial(request, store);
  }
}

src/storage/artifacts/identity.ts:
/**
 * cp1 — producer attribution and the expected schema version.
 *
 * `ArtifactRef.producer` is required by the frozen table, and `ActorRef` fixes one rule this lane
 * can decide: a `human` producer must carry the identity reference the authority root verified.
 * A human claim with `identityRef: null` is therefore an unattributable producer, refused as a
 * binding mismatch rather than accepted on the strength of the label.
 *
 * `ArtifactRef.schema` is the version triple (`name`/`version`/`digest`). A consumer that expects a
 * version compares all three: a matching name at a different version, or the same name/version with
 * different schema bytes, is a different artifact contract, not a near miss.
 */
import { storeFail, storeOk } from '../index.js';
import type { StoreResult } from '../index.js';
import type { ActorRef, ArtifactRef, SchemaRef } from './types.js';

/**
 * The producer identity of a reference, or a refusal when the reference cannot be attributed to a
 * subject at all.
 */
export function attributeProducer(ref: ArtifactRef): StoreResult<ActorRef> {
  if (ref.producer.kind === 'human' && ref.producer.identityRef === null) {
    return storeFail(
      'EFK_ARTIFACT_BINDING_MISMATCH',
      `artifact ${ref.id} claims a human producer with no verified identity reference`,
      [ref.id],
    );
  }
  return storeOk(ref.producer);
}

/** The declared schema triple, or a refusal when it is not the version the consumer expects. */
export function matchSchema(ref: ArtifactRef, expected: SchemaRef): StoreResult<SchemaRef> {
  const declared = ref.schema;
  if (declared.name !== expected.name || declared.version !== expected.version || declared.digest !== expected.digest) {
    return storeFail(
      'EFK_ARTIFACT_BINDING_MISMATCH',
      `artifact ${ref.id} declares schema ${declared.name}@${declared.version}, the consumer expects ${expected.name}@${expected.version}`,
      [ref.id],
    );
  }
  return storeOk(declared);
}

src/storage/artifacts/types.ts:
/**
 * The artifact-reference contract this lane reads: who produced a reference, which attempt it is
 * bound to, and who is allowed to read it. Every field name below is a frozen `SCHEMAS.md` name
 * (`ArtifactRef`, `Binding`, `GraphRef`, `SchemaRef`, `ActorRef`); nothing is renamed or re-declared.
 *
 * The `Wire` mapping widens two kinds of slot, so three aliases below re-narrow what this lane
 * actually reads — the same move `../contracts.ts` makes for `EventPayload`:
 *
 * - a nested `$ref` to an object definition (`producer`, `schema`, `binding.graph`) becomes
 *   `Record<string, unknown>` because `Wire` maps the referenced schema node, not its `Decoded`
 *   form;
 * - an `anyOf` resolves to its first branch, so `binding` and `expiresAt` are typed non-null and
 *   `Binding.baseDigest` and `hostSessionId` are typed as plain `string`s, although the frozen
 *   table allows `null`.
 *
 * Every narrowing still points at the same frozen definition, so no field is renamed or re-declared.
 */
import type { Decoded } from '../../protocol/index.js';
import type { ArtifactRef as Wire, ArtifactStore } from '../index.js';

export type { ArtifactStore };
export type WireArtifactRef = Wire;
export type GraphRef = Decoded<'GraphRef'>;
export type SchemaRef = Decoded<'SchemaRef'>;
export type ActorRef = Omit<Decoded<'ActorRef'>, 'identityRef'> & { readonly identityRef: Wire | null };

/** The attempt binding, with its graph and nullable slots back to their frozen definitions. */
export type Binding = Omit<Decoded<'Binding'>, 'graph' | 'baseDigest' | 'hostSessionId'> & {
  readonly graph: GraphRef;
  readonly baseDigest: string | null;
  readonly hostSessionId: Decoded<'Binding'>['hostSessionId'] | null;
};

/** An immutable artifact reference, with its nested references and nullable slots re-narrowed. */
export type ArtifactRef = Omit<Wire, 'producer' | 'schema' | 'binding' | 'expiresAt'> & {
  readonly producer: ActorRef;
  readonly schema: SchemaRef;
  readonly binding: Binding | null;
  readonly expiresAt: number | null;
};

/** The frozen information level (`$defs/Visibility`). */
export type Visibility = WireArtifactRef['visibility'];
/** The frozen source partition (`ArtifactRef.partition`; not inferred from visibility). */
export type Partition = WireArtifactRef['partition'];
/** UTC epoch milliseconds, supplied by the caller's injected Clock (I07) — never read here. */
export type Instant = number;

/**
 * Who is reading. A13 pairs every read path with its audience; `report` is the default report view
 * an author or operator sees, `asset-staging` is the asset writer's view.
 */
export type Audience = 'author' | 'evaluator' | 'report' | 'asset-staging';
export type ConsumerRole = 'workspace' | 'evaluator' | 'asset';

/**
 * The attempt an artifact is expected to belong to. `baseDigest` is the workspace snapshot the
 * attempt started from, and `null` means the attempt has no workspace snapshot at all.
 */
export type BindingExpectation = Binding;

/**
 * What kind of reference a consumer is holding out for.
 *
 * `node-product` is an artifact produced *by* an attempt: S09 requires a complete binding, so the
 * expectation carries one. `pre-source` is an approval, source pin or protocol snapshot that may be
 * produced before any attempt exists; its binding may be `null` and only becomes bound when a
 * consuming command supplies the exact session/task/graph/digest, which is what a non-null
 * `binding` expectation here means. The union makes an unbound node product unrepresentable.
 */
export type ArtifactExpectation =
  | { readonly productKind: 'node-product'; readonly schema: SchemaRef; readonly binding: BindingExpectation }
  | { readonly productKind: 'pre-source'; readonly schema: SchemaRef; readonly binding: BindingExpectation | null };

/** The executor-visible partition of a reference set. Withheld references are counted, never named. */
export interface FeedbackPartition {
  readonly audience: Audience;
  readonly visible: readonly ArtifactRef[];
  readonly withheldVisibility: number;
  readonly withheldPartition: number;
}

/** An artifact a consumer has read: real bytes, not a summary of them. */
export interface AdmittedArtifact {
  readonly ref: ArtifactRef;
  readonly bytes: string;
}

export interface ConsumerAdmission {
  readonly role: ConsumerRole;
  readonly audience: Audience;
  readonly evidence: readonly AdmittedArtifact[];
}

interface BoundRefsRequest {
  readonly refs: readonly ArtifactRef[];
  readonly expectation: ArtifactExpectation;
  readonly at: Instant;
}

export type WorkspaceConsumerRequest = { readonly role: 'workspace' } & BoundRefsRequest;
export type EvaluatorConsumerRequest = { readonly role: 'evaluator' } & BoundRefsRequest;

/**
 * Asset material. `contentRefs` and `sourceTraces` are the decoded arrays of a `CapabilityAsset`
 * (each must contain at least one reference, as required by the frozen `minItems: 1` rules). This
 * request is also constructible directly, so the consumer rejects either empty list before reads.
 * `revokedDependencies` names
 * the asset dependencies whose revocation has invalidated this qualification (S17); it is an input
 * because the registry that observed the revocation owns that fact.
 */
export interface AssetConsumerRequest {
  readonly role: 'asset';
  readonly contentRefs: readonly ArtifactRef[];
  readonly sourceTraces: readonly ArtifactRef[];
  readonly revokedDependencies: readonly string[];
  readonly at: Instant;
}

export type ConsumerRequest = WorkspaceConsumerRequest | EvaluatorConsumerRequest | AssetConsumerRequest;

src/storage/memory-event-store.ts:
/**
 * A memory reference `EventStore`: one writer per session, a CAS revision, and an outbox that is a
 * projection of the same journal.
 *
 * The store never decides or executes anything. It validates a transaction and commits it, or it
 * refuses and commits nothing. Its only "extra" state beyond the journal is the content that events
 * reference (effects and receipts) and the request-identity index used to answer a repeated
 * submission with `duplicate` instead of a second commit.
 *
 * `nextEffects` returns only `intended` effects whose binding is still at the current epoch; once
 * `effect.dispatched` is committed the effect is `unknown` and `reconcileEffect` is the only way
 * forward. Effects intended at an earlier epoch surface as `staleEffectIds` instead of being handed
 * out as sendable. That is the store-side meaning of "an unknown external effect is reconciled, not
 * resent".
 */
import { decodeProtocolVersion, gateRuntimeVersion } from '../protocol/index.js';
import type {
  AppendOutcome,
  AppendRequest,
  CreateSessionInput,
  DispatchInput,
  Effect,
  EventDraft,
  EventPayload,
  EventStore,
  ExportedSession,
  JournalProjection,
  OutboxProjection,
  ReceiptInput,
  ReceiptOutcome,
  SessionHandle,
  StoreResult,
} from './contracts.js';
import { storeFail, storeOk } from './contracts.js';
import { canonical, type DigestPort } from './identity.js';
import { intendedIds, projectOutbox, reconcileIds } from './outbox.js';
import { replay } from './projection.js';
import { commitBatch, newSessionRecord, reviveSession, type SessionRecord } from './store-session.js';

/** A fully-populated `EventPayload`; omitted members are the explicit nulls/empties the schema requires. */
function payloadOf(overrides: Partial<EventPayload>): EventPayload {
  return {
    binding: null,
    objectRef: null,
    before: null,
    after: null,
    effectId: null,
    decisionId: null,
    changedIds: [],
    error: null,
    ...overrides,
  };
}

export interface MemoryEventStore extends EventStore {
  restoreSession(exported: ExportedSession): StoreResult<SessionHandle>;
  sessionIds(): readonly string[];
}

export function createMemoryEventStore(options: { readonly digest: DigestPort }): MemoryEventStore {
  const { digest } = options;
  const sessions = new Map<string, SessionRecord>();

  const handleOf = (session: SessionRecord): SessionHandle => ({
    sessionId: session.sessionId,
    epoch: session.epoch,
    schemaVersion: session.protocol.schemaVersion,
  });

  const requireSession = (sessionId: string): StoreResult<SessionRecord> => {
    const session = sessions.get(sessionId);
    if (session === undefined) return storeFail('EFK_SCHEMA_INVALID', `unknown session ${sessionId}`, [sessionId]);
    return storeOk(session);
  };

  const project = (session: SessionRecord): StoreResult<OutboxProjection> =>
    projectOutbox(session.events, session.effects, session.receipts);

  const applyReceiptTo = (session: SessionRecord, input: ReceiptInput): StoreResult<ReceiptOutcome> => {
    const { receipt } = input;
    const effect = session.effects.get(receipt.effectId);
    if (effect === undefined) return storeFail('EFK_SCHEMA_INVALID', `receipt references unknown effect ${receipt.effectId}`, [receipt.effectId]);
    if (input.objectRef.id !== receipt.receiptId) {
      return storeFail('EFK_ARTIFACT_BINDING_MISMATCH', `objectRef ${input.objectRef.id} does not carry receipt ${receipt.receiptId}`, [receipt.receiptId]);
    }
    const existing = session.receipts.get(receipt.receiptId);
    if (existing !== undefined) {
      if (canonical(existing) !== canonical(receipt)) {
        return storeFail('EFK_IDEMPOTENCY_COLLISION', `receipt ${receipt.receiptId} is already committed with different content`, [receipt.receiptId]);
      }
      return storeOk({ disposition: 'duplicate', revision: session.revision, effectId: receipt.effectId, receiptId: receipt.receiptId });
    }
    const projection = project(session);
    if (!projection.ok) return projection;
    const entry = projection.value.entries.find((candidate) => candidate.effectId === receipt.effectId);
    if (entry === undefined) return storeFail('EFK_SCHEMA_INVALID', `receipt references unknown effect ${receipt.effectId}`, [receipt.effectId]);
    if (entry.state !== 'dispatched' && entry.state !== 'unknown') {
      return storeFail('EFK_CLAIM_CONFLICT', `effect ${receipt.effectId} is ${entry.state}; a receipt requires a dispatched effect`, [receipt.effectId]);
    }
    const stale = receipt.binding.epoch !== input.epoch || canonical(receipt.binding) !== canonical(effect.binding);
    if (receipt.status !== 'unknown' && receipt.observability.length === 0) {
      return storeFail('EFK_EFFECT_UNKNOWN', `receipt ${receipt.receiptId} claims ${receipt.status} for effect ${receipt.effectId} without observability`, [receipt.effectId]);
    }
    const draft: EventDraft = {
      protocol: session.protocol,
      eventId: receipt.receiptId,
      sessionId: session.sessionId,
      epoch: input.epoch,
      causedBy: receipt.receiptId,
      type: stale ? 'receipt.archived' : 'receipt.applied',
      payload: payloadOf({ binding: effect.binding, objectRef: input.objectRef, effectId: receipt.effectId, changedIds: [receipt.effectId] }),
      visibility: 'internal',
    };
    const committed = commitBatch(digest, session, `receipt:${receipt.receiptId}`, input.expectedRevision, input.epoch, [draft], [], [receipt]);
    if (!committed.ok) return committed;
    return storeOk({
      disposition: stale ? 'archived' : 'applied',
      revision: committed.value.revision,
      effectId: receipt.effectId,
      receiptId: receipt.receiptId,
    });
  };

  const dispatchTo = (session: SessionRecord, input: DispatchInput): StoreResult<AppendOutcome> => {
    const projection = project(session);
    if (!projection.ok) return projection;
    const entry = projection.value.entries.find((candidate) => candidate.effectId === input.effectId);
    if (entry === undefined) return storeFail('EFK_SCHEMA_INVALID', `unknown effect ${input.effectId}`, [input.effectId]);
    if (entry.state !== 'intended') {
      return storeFail('EFK_CLAIM_CONFLICT', `effect ${input.effectId} is ${entry.state}; only an intended effect is dispatchable`, [input.effectId]);
    }
    const effect = session.effects.get(input.effectId) as Effect;
    if (effect.binding.epoch !== session.epoch) {
      return storeFail('EFK_LEASE_STALE', `effect ${input.effectId} was intended at epoch ${effect.binding.epoch}, session is at ${session.epoch}`, [input.effectId]);
    }
    const draft: EventDraft = {
      protocol: session.protocol,
      eventId: input.claimId,
      sessionId: session.sessionId,
      epoch: input.epoch,
      causedBy: input.claimId,
      type: 'effect.dispatched',
      payload: payloadOf({ binding: effect.binding, effectId: input.effectId, changedIds: [input.effectId] }),
      visibility: 'internal',
    };
    return commitBatch(digest, session, `dispatch:${input.claimId}`, input.expectedRevision, input.epoch, [draft], [], []);
  };

  const reconcileTo = (session: SessionRecord, input: ReceiptInput): StoreResult<ReceiptOutcome> => {
    const { receipt } = input;
    if (session.receipts.has(receipt.receiptId)) {
      return applyReceiptTo(session, input);
    }
    if (receipt.status === 'unknown' || receipt.observability.length === 0) {
      return storeFail('EFK_EFFECT_UNKNOWN', `effect ${receipt.effectId} still has no actual observability; it stays unknown`, [receipt.effectId]);
    }
    const projection = project(session);
    if (!projection.ok) return projection;
    const entry = projection.value.entries.find((candidate) => candidate.effectId === receipt.effectId);
    if (entry === undefined) return storeFail('EFK_SCHEMA_INVALID', `reconcile references unknown effect ${receipt.effectId}`, [receipt.effectId]);
    if (entry.state !== 'dispatched' && entry.state !== 'unknown') {
      return storeFail('EFK_CLAIM_CONFLICT', `effect ${receipt.effectId} is ${entry.state}; there is nothing to reconcile`, [receipt.effectId]);
    }
    return applyReceiptTo(session, input);
  };

  return {
    createSession(input: CreateSessionInput): StoreResult<SessionHandle> {
      const decoded = decodeProtocolVersion(input.protocol);
      if (!decoded.ok) return decoded;
      if (gateRuntimeVersion(decoded.value) === 'unsupported') {
        return storeFail('EFK_PROTOCOL_UNSUPPORTED', `unsupported protocol ${decoded.value.namespace}@${decoded.value.schemaVersion}`);
      }
      const existing = sessions.get(input.sessionId);
      if (existing !== undefined) {
        if (existing.epoch === input.epoch && canonical(existing.protocol) === canonical(decoded.value)) {
          return storeOk(handleOf(existing));
        }
        return storeFail('EFK_REVISION_CONFLICT', `session ${input.sessionId} already exists at epoch ${existing.epoch}`, [input.sessionId]);
      }
      const session = newSessionRecord(input.sessionId, input.epoch, decoded.value);
      sessions.set(input.sessionId, session);
      return storeOk(handleOf(session));
    },

    append(request: AppendRequest): StoreResult<AppendOutcome> {
      const found = requireSession(request.sessionId);
      if (!found.ok) return found;
      return commitBatch(digest, found.value, request.requestId, request.expectedRevision, request.epoch, request.events, request.effects, request.receipts);
    },

    exportSession(sessionId: string): StoreResult<ExportedSession> {
      const found = requireSession(sessionId);
      if (!found.ok) return found;
      const session = found.value;
      return storeOk({
        sessionId: session.sessionId,
        epoch: session.epoch,
        protocol: session.protocol,
        revision: session.revision,
        events: [...session.events],
        effects: [...session.effects.values()],
        receipts: [...session.receipts.values()],
      });
    },

    replay(sessionId: string): StoreResult<JournalProjection> {
      const found = requireSession(sessionId);
      if (!found.ok) return found;
      const session = found.value;
      const state = replay(session.events);
      if (!state.ok) return state;
      const projection = project(session);
      if (!projection.ok) return projection;
      const pendingEffectIds: string[] = [];
      const staleEffectIds: string[] = [];
      for (const effectId of intendedIds(projection.value)) {
        const effect = session.effects.get(effectId) as Effect;
        (effect.binding.epoch === state.value.epoch ? pendingEffectIds : staleEffectIds).push(effectId);
      }
      return storeOk({
        ...state.value,
        pendingEffectIds,
        unknownEffectIds: reconcileIds(projection.value),
        staleEffectIds,
      });
    },

    outbox(sessionId: string): StoreResult<OutboxProjection> {
      const found = requireSession(sessionId);
      if (!found.ok) return found;
      return project(found.value);
    },

    nextEffects(sessionId: string): StoreResult<readonly Effect[]> {
      const found = requireSession(sessionId);
      if (!found.ok) return found;
      const session = found.value;
      const projection = project(session);
      if (!projection.ok) return projection;
      const effects: Effect[] = [];
      for (const effectId of intendedIds(projection.value)) {
        const effect = session.effects.get(effectId) as Effect;
        if (effect.binding.epoch === session.epoch) effects.push(effect);
      }
      return storeOk(effects);
    },

    dispatchEffect(sessionId: string, input: DispatchInput): StoreResult<AppendOutcome> {
      const found = requireSession(sessionId);
      if (!found.ok) return found;
      return dispatchTo(found.value, input);
    },

    applyReceipt(sessionId: string, input: ReceiptInput): StoreResult<ReceiptOutcome> {
      const found = requireSession(sessionId);
      if (!found.ok) return found;
      return applyReceiptTo(found.value, input);
    },

    reconcileEffect(sessionId: string, input: ReceiptInput): StoreResult<ReceiptOutcome> {
      const found = requireSession(sessionId);
      if (!found.ok) return found;
      return reconcileTo(found.value, input);
    },

    restoreSession(exported: ExportedSession): StoreResult<SessionHandle> {
      if (sessions.has(exported.sessionId)) {
        return storeFail('EFK_REVISION_CONFLICT', `session ${exported.sessionId} is already open`, [exported.sessionId]);
      }
      const revived = reviveSession(exported);
      if (!revived.ok) return revived;
      sessions.set(exported.sessionId, revived.value);
      return storeOk(handleOf(revived.value));
    },

    sessionIds(): readonly string[] {
      return [...sessions.keys()];
    },
  };
}

