/** Thin application service. Construction is inert; all outside capabilities are parameter ports. */
import { canonical, storeFail, storeOk } from '../../storage/index.js';
import { openBudgetLedger } from '../../kernel/policy/index.js';
import { project } from './project.js';
import { commit, event, idFor, putObject } from './journal.js';
import { planReceipt, notExecutedReceipt } from './receipts.js';
import { stepSession } from './dispatch.js';
import { pauseSession, resumeSession, cancelSession } from './controls.js';
import { evaluateSession } from './evaluation.js';
import type { ReceiptOutcome } from '../../storage/index.js';
import type { RuntimeState, SessionPorts, SessionSeed, SessionService, StoreResult, ReconcileReport } from './types.js';

export function createSessionService(ports: SessionPorts): SessionService {
  const seeds = new Map<string, SessionSeed>();
  function seedOf(sessionId: string): StoreResult<SessionSeed> {
    const seed = seeds.get(sessionId);
    return seed === undefined ? storeFail('EFK_SCHEMA_INVALID', 'session has no registered seed', [sessionId]) : storeOk(seed);
  }
  function read(sessionId: string): StoreResult<RuntimeState> {
    const seed = seedOf(sessionId);
    if (!seed.ok) return seed;
    const exported = ports.store.exportSession(sessionId);
    if (!exported.ok) return exported;
    const graphPin = exported.value.events.find(e => e.type === 'graph.accepted');
    const seedPin = exported.value.events.find(e => e.type === 'budget.changed');
    if ((graphPin !== undefined && graphPin.payload.objectRef!.digest !== ports.digest.digest(canonical(seed.value.graph.spec)))
      || (seedPin !== undefined && seedPin.payload.objectRef!.digest !== ports.digest.digest(canonical(seedSnapshot(seed.value))))) {
      return storeFail('EFK_SOURCE_PIN_DRIFT', 'session seed differs from its committed graph/policy/operation snapshot', [sessionId]);
    }
    return project(exported.value, seed.value);
  }
  function receive(sessionId: string, input: unknown): StoreResult<ReceiptOutcome> {
    const state = read(sessionId);
    if (!state.ok) return state;
    const seed = seedOf(sessionId);
    if (!seed.ok) return seed;
    const batch = planReceipt(ports, seed.value, state.value, input, ports.clock.now());
    if (!batch.ok) return batch;
    if (batch.value.disposition === 'duplicate') return storeOk({ disposition: 'duplicate', revision: state.value.revision,
      effectId: batch.value.receipt.effectId, receiptId: batch.value.receipt.receiptId });
    // The same reducer owns metering judgement before commit and during replay. Incomplete usage
    // retains its reservation; conflicting evidence cannot advance the attempt/outbox. Actual
    // overspend is committed and exposed rather than hidden by refusing its measurement.
    const preview = project({ sessionId, epoch: state.value.epoch, protocol: state.value.protocol,
      revision: state.value.revision + 1, effects: Object.values(state.value.effects),
      receipts: [...Object.values(state.value.receipts), ...batch.value.receipts],
      events: [...state.value.events, ...batch.value.events.map((e, i) => ({ ...e,
        revision: state.value.revision + 1, sequence: (state.value.lastSequence ?? -1) + 1 + i }))] }, seed.value);
    if (!preview.ok) return preview;
    const conflict = preview.value.usageIssues.slice(state.value.usageIssues.length)
      .find(e => e.code !== 'EFK_USAGE_INCOMPLETE' && e.code !== 'EFK_BUDGET_EXHAUSTED');
    if (conflict !== undefined) return { ok: false, error: conflict };
    const committed = commit(ports, state.value, { commandId: batch.value.events[0].causedBy,
      expectedRevision: state.value.revision }, batch.value);
    return committed.ok ? storeOk({ disposition: batch.value.disposition, revision: committed.value.revision,
      effectId: batch.value.receipt.effectId, receiptId: batch.value.receipt.receiptId }) : committed;
  }
  async function reconcile(sessionId: string): Promise<StoreResult<ReconcileReport>> {
    const readState = read(sessionId);
    if (!readState.ok) return readState;
    const targetIds = readState.value.unknownEffectIds;
    const response = await ports.host.reconcile({ sessionId, targetIds });
    if (!response.ok) return response;
    const resolved: string[] = [], notExecuted: string[] = [];
    for (const outcome of response.value) {
      // Real host reconciliation boundary: an unrelated verdict cannot settle another effect.
      if (!targetIds.includes(outcome.effectId)) return storeFail('EFK_ARTIFACT_BINDING_MISMATCH', 'reconcile returned an unrequested effect', [outcome.effectId]);
      if (outcome.verdict === 'unknown') continue;
      if (outcome.error !== null) return { ok: false, error: outcome.error };
      if (outcome.verdict === 'resolved' && (outcome.receipt === null || outcome.receipt.effectId !== outcome.effectId || outcome.receipt.status === 'unknown')) {
        return storeFail('EFK_EFFECT_UNKNOWN', 'resolved reconciliation has no matching actual receipt', [outcome.effectId]);
      }
      const effect = readState.value.effects[outcome.effectId];
      const receipt = outcome.verdict === 'not-executed'
        ? notExecutedReceipt(ports, effect, 'host-reconcile-not-executed') : outcome.receipt!;
      const applied = receive(sessionId, receipt);
      if (!applied.ok) return applied;
      if (applied.value.disposition !== 'archived') (outcome.verdict === 'not-executed' ? notExecuted : resolved).push(outcome.effectId);
    }
    const current = read(sessionId);
    if (!current.ok) return current;
    return storeOk({ sessionId, resolved, notExecuted, unknown: current.value.unknownEffectIds });
  }
  const service: SessionService = {
    create(request) {
      const budget = openBudgetLedger(request.policy, request.reservePerRequest);
      if (!budget.ok) return budget;
      if (request.graphRef.graphId !== request.graph.graphId || request.graphRef.revision !== request.graph.revision
        || request.graphRef.digest !== ports.digest.digest(canonical(request.graph.spec))) {
        return storeFail('EFK_SOURCE_PIN_DRIFT', 'graph seed does not match its pinned reference');
      }
      const created = ports.store.createSession(request);
      if (!created.ok) return created;
      seeds.set(request.sessionId, request);
      const state = read(request.sessionId);
      if (!state.ok) return state;
      if (state.value.events.length === 0) {
        const ref = putObject(ports, state.value, idFor(ports, 'graph', request.graphRef), 'GraphSpec', request.graph.spec, null);
        if (!ref.ok) return ref;
        const commandId = idFor(ports, 'create', request.sessionId);
        const seedRef = putObject(ports, state.value, idFor(ports, 'seed', request.sessionId), 'SessionSeed', seedSnapshot(request), null);
        if (!seedRef.ok) return seedRef;
        const accepted = commit(ports, state.value, { commandId, expectedRevision: 0 },
          { events: [event(state.value, commandId, 'graph', 'graph.accepted', { objectRef: ref.value }),
            event(state.value, commandId, 'seed', 'budget.changed', { objectRef: seedRef.value })], effects: [], receipts: [] });
        if (!accepted.ok) return accepted;
      }
      return created;
    },
    open(seed) {
      seeds.set(seed.sessionId, seed);
      return read(seed.sessionId);
    },
    read, receive, reconcile,
    async step(sessionId) {
      const seed = seedOf(sessionId);
      return seed.ok ? stepSession(ports, seed.value, service) : seed;
    },
    pause(sessionId, request) {
      const state = read(sessionId);
      return state.ok ? pauseSession(ports, state.value, request) : state;
    },
    resume(sessionId, request) {
      const state = read(sessionId), seed = seedOf(sessionId);
      if (!state.ok) return state;
      return seed.ok ? resumeSession(ports, seed.value, state.value, request) : seed;
    },
    async cancel(sessionId, request) {
      const state = read(sessionId), seed = seedOf(sessionId);
      if (!state.ok) return state;
      return seed.ok ? cancelSession(ports, seed.value, service, state.value, request) : seed;
    },
    async evaluate(sessionId, effectId) {
      const state = read(sessionId), seed = seedOf(sessionId);
      if (!state.ok) return state;
      return seed.ok ? evaluateSession(ports, seed.value, state.value, effectId) : seed;
    },
    async observe(sessionId) {
      const state = read(sessionId);
      if (!state.ok) return state;
      const observed = await ports.host.observe(sessionId);
      if (!observed.ok) return observed;
      const commandId = idFor(ports, 'observe', [sessionId, state.value.revision]);
      const ref = putObject(ports, state.value, commandId, 'HostObservation', observed.value, null,
        { actorId: 'host', kind: 'host-adapter', identityRef: null });
      if (!ref.ok) return ref;
      const committed = commit(ports, state.value, { commandId, expectedRevision: state.value.revision },
        { events: [event(state.value, commandId, 'observed', 'host.observed', { objectRef: ref.value })], effects: [], receipts: [] });
      return committed.ok ? observed : committed;
    },
    close: sessionId => ports.store.exportSession(sessionId),
  };
  return service;
}

function seedSnapshot(seed: SessionSeed): unknown {
  return { graphRef: seed.graphRef, policy: seed.policy, reservePerRequest: seed.reservePerRequest,
    operations: seed.operations, grants: seed.grants };
}

src/runtime/session/types.ts:
/** Session application ports; no backend, permission root or evaluator is discovered. */
import type { Decoded, ErrorEnvelope, Instant } from '../../protocol/index.js';
import type { CompiledGraph, NodeSpec } from '../../kernel/graph/index.js';
import type { BudgetLedger, BudgetPolicy, RiskInput } from '../../kernel/policy/index.js';
import type { SchedulerState } from '../../kernel/scheduler/index.js';
import type {
  ArtifactRef, ArtifactStore, DigestPort, DispatchMode, Effect, Event, EventDraft,
  EventStore, ExportedSession, NodeStateEntry, OutboxProjection, Receipt, ReceiptOutcome,
  SessionHandle, StoreResult,
} from '../../storage/index.js';
import type { Clock, DelegationGrant, HostObservation, HostPort } from '../host-port/index.js';

export type { ArtifactRef, Binding, Effect, Event, EventDraft, Receipt, StoreResult };
type Binding = Decoded<'Binding'>;
type GraphRef = Decoded<'GraphRef'>;
/** Explicit node operations: a node name never implicitly becomes a tool invocation. */
export type NodeOperation = Pick<Effect, 'kind' | 'payload' | 'inputRefs'>;
export interface SessionSeed {
  readonly sessionId: string;
  readonly graph: CompiledGraph;
  readonly graphRef: GraphRef;
  readonly policy: BudgetPolicy;
  readonly reservePerRequest: number;
  readonly grants: readonly DelegationGrant[];
  readonly operations: Readonly<Record<string, NodeOperation>>;
}
export interface RuntimeState {
  readonly sessionId: string;
  readonly protocol: Decoded<'ProtocolVersion'>;
  readonly epoch: number;
  readonly revision: number;
  readonly lastSequence: number | null;
  readonly dispatchMode: DispatchMode;
  readonly cancellation: 'none' | 'requested' | 'confirmed' | 'unconfirmed';
  readonly attempts: Readonly<Record<string, number>>;
  readonly nodeStates: readonly NodeStateEntry[];
  readonly effects: Readonly<Record<string, Effect>>;
  readonly receipts: Readonly<Record<string, Receipt>>;
  readonly resourceModes: Readonly<Record<string, 'exclusive' | 'shared'>>;
  readonly events: readonly Event[];
  readonly outbox: OutboxProjection;
  readonly budget: BudgetLedger;
  readonly usageIssues: readonly ErrorEnvelope[];
  readonly appliedInvocations: readonly string[];
  readonly invocationEffects: Readonly<Record<string, string>>;
  readonly scheduler: SchedulerState;
  readonly intents: readonly Effect[];
  readonly unknownEffectIds: readonly string[];
  readonly staleEffectIds: readonly string[];
  readonly archivedReceiptIds: readonly string[];
}
export interface PlannedBatch {
  readonly events: readonly EventDraft[];
  readonly effects: readonly Effect[];
  readonly receipts: readonly Receipt[];
}
export interface SessionCommand { readonly commandId: string; readonly expectedRevision: number }
export interface PauseRequest extends SessionCommand { readonly reason: string }
export interface ResumeRequest extends SessionCommand { readonly epoch: number; readonly manifestRef: ArtifactRef }
export interface CancelRequest extends SessionCommand { readonly reason: string }
export interface RoundPlan {
  readonly now: Instant;
  readonly leaseTtlMs: number;
  readonly effectTtlMs: number;
  readonly maxConcurrentAgents: number;
  readonly depth: number;
  readonly maxDepth: number;
}
export type Admission = Omit<RiskInput, 'budget' | 'usage'>;
export interface PolicyPort {
  /** Pinned inputs; the only decision is kernel/policy.decide. */
  inspect(seed: SessionSeed, node: NodeSpec, binding: Binding, now: Instant): Admission;
  /** Re-admit exact manifest/schema/host session before committing a new epoch. */
  resume(seed: SessionSeed, state: RuntimeState, request: ResumeRequest): StoreResult<void>;
}
export interface EvaluatorPort {
  readonly issuer: Decoded<'ActorRef'>;
  evaluateTask(seed: SessionSeed, state: RuntimeState, receipt: Receipt): Promise<StoreResult<unknown>>;
}
export interface SessionPorts extends Omit<RoundPlan, 'now'> {
  readonly store: EventStore;
  readonly artifacts: ArtifactStore;
  readonly host: HostPort;
  readonly clock: Clock;
  readonly digest: DigestPort;
  readonly policy: PolicyPort;
  readonly evaluator: EvaluatorPort;
}
export interface CommandOutcome {
  readonly sessionId: string;
  readonly revision: number;
  readonly eventIds: readonly string[];
  readonly effectIds: readonly string[];
}
export interface StepReport {
  readonly sessionId: string;
  readonly revision: number;
  readonly dispatchAttempted: readonly string[];
  readonly appliedReceipts: readonly string[];
  readonly archivedReceipts: readonly string[];
  readonly unknownEffectIds: readonly string[];
}
export interface CancelReport extends StepReport { readonly status: 'cancelled' | 'unknown'; readonly error: ErrorEnvelope | null }
export interface ReconcileReport {
  readonly sessionId: string;
  readonly resolved: readonly string[];
  readonly notExecuted: readonly string[];
  readonly unknown: readonly string[];
}
export interface CreateSessionRequest extends SessionSeed { readonly epoch: number; readonly protocol: unknown }
export interface SessionService {
  create(request: CreateSessionRequest): StoreResult<SessionHandle>;
  open(seed: SessionSeed): StoreResult<RuntimeState>;
  read(sessionId: string): StoreResult<RuntimeState>;
  step(sessionId: string): Promise<StoreResult<StepReport>>;
  pause(sessionId: string, request: PauseRequest): StoreResult<CommandOutcome>;
  resume(sessionId: string, request: ResumeRequest): StoreResult<CommandOutcome>;
  cancel(sessionId: string, request: CancelRequest): Promise<StoreResult<CancelReport>>;
  receive(sessionId: string, receipt: unknown): StoreResult<ReceiptOutcome>;
  evaluate(sessionId: string, effectId: string): Promise<StoreResult<CommandOutcome>>;
  observe(sessionId: string): Promise<StoreResult<HostObservation>>;
  reconcile(sessionId: string): Promise<StoreResult<ReconcileReport>>;
  close(sessionId: string): StoreResult<ExportedSession>;
}

test/l2-artifact-access.test.js:
/**
 * l2_artifact_port cp2 — the access partition (A13 + `PrivacyPolicy`) and expiry semantics.
 *
 * Visibility and source partition are independent axes, so each one alone can withhold a reference.
 * The withheld side of a partition is a count, never an id: A13 forbids the executor-visible path
 * from containing the reference at all.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';

import { createMemoryArtifactStore } from '../dist/storage/index.js';
import {
  defaultReportRefs,
  partitionFeedback,
  readArtifact,
  visibilityCeiling,
  withheldReason,
} from '../dist/storage/artifacts/index.js';

const PROTOCOL = { namespace: 'evofence.runtime/1', schemaVersion: '1.1.0' };
const digestPort = {
  digest: (bytes) => `sha256:${createHash('sha256').update(bytes, 'utf8').digest('hex')}`,
};
const DIGEST = (seed) => digestPort.digest(String(seed));

const ok = (result, what) => {
  assert.equal(result.ok, true, `${what ?? 'call'} expected success, got ${JSON.stringify(result.error)}`);
  return result.value;
};
const err = (result, code, what) => {
  assert.equal(result.ok, false, `${what ?? 'call'} expected a typed rejection`);
  assert.equal(result.error.code, code, `${what ?? 'call'} rejected with ${result.error.code}`);
  return result.error;
};

function artifact(id, over = {}) {
  const { content = id, ...rest } = over;
  return {
    protocol: PROTOCOL,
    id,
    digest: DIGEST(content),
    producer: { actorId: 'kernel-1', kind: 'kernel', identityRef: null },
    binding: null,
    schema: { name: 'TaskEvidenceReport', version: '1.1.0', digest: DIGEST('schema') },
    location: `artifact://${id}`,
    visibility: 'internal',
    expiresAt: null,
    partition: 'not-evaluation',
    ...rest,
  };
}

test('each audience has the documented information ceiling', () => {
  assert.equal(visibilityCeiling('author'), 'internal');
  assert.equal(visibilityCeiling('report'), 'internal');
  assert.equal(visibilityCeiling('asset-staging'), 'internal');
  assert.equal(visibilityCeiling('evaluator'), 'final');
});

test('an author-facing audience is withheld from private, held-out and final artifacts', () => {
  for (const audience of ['author', 'report', 'asset-staging']) {
    for (const visibility of ['private', 'held-out', 'final']) {
      assert.equal(ok(withheldReason(artifact('art-1', { visibility }), audience)), 'visibility', `${audience}/${visibility}`);
    }
    for (const visibility of ['public', 'internal']) {
      assert.equal(ok(withheldReason(artifact('art-1', { visibility }), audience)), 'none', `${audience}/${visibility}`);
    }
  }
});

test('a held-out or final source partition is withheld from an author even at internal visibility', () => {
  assert.equal(ok(withheldReason(artifact('art-1', { partition: 'held-out' }), 'author')), 'partition');
  assert.equal(ok(withheldReason(artifact('art-1', { partition: 'final' }), 'report')), 'partition');
  assert.equal(ok(withheldReason(artifact('art-1', { partition: 'train' }), 'author')), 'none');
  assert.equal(ok(withheldReason(artifact('art-1', { partition: 'dev' }), 'author')), 'none');
});

test('the evaluator audience withholds nothing', () => {
  for (const visibility of ['public', 'internal', 'private', 'held-out', 'final']) {
    for (const partition of ['train', 'dev', 'held-out', 'final', 'not-evaluation']) {
      assert.equal(ok(withheldReason(artifact('art-1', { visibility, partition }), 'evaluator')), 'none');
    }
  }
});

test('the default report carries the author-visible references and counts the rest by reason', () => {
  const refs = [
    artifact('reportable', { visibility: 'internal' }),
    artifact('secret', { visibility: 'private' }),
    artifact('holdout', { visibility: 'internal', partition: 'held-out' }),
    artifact('final', { visibility: 'final' }),
  ];
  const partition = ok(defaultReportRefs(refs));
  assert.equal(partition.audience, 'report');
  assert.deepEqual(partition.visible.map((ref) => ref.id), ['reportable']);
  assert.equal(partition.withheldVisibility, 2);
  assert.equal(partition.withheldPartition, 1);
});

test('the sensitive trace does not appear in the default report, not even by id', () => {
  const refs = [
    artifact('reportable', { visibility: 'internal' }),
    artifact('heldout-repo-42-patch', { visibility: 'held-out', partition: 'held-out', location: 'artifact://private/heldout-repo-42-patch' }),
  ];
  const rendered = JSON.stringify(ok(defaultReportRefs(refs)));
  assert.doesNotMatch(rendered, /heldout-repo-42-patch/);
  assert.doesNotMatch(rendered, /private\/heldout/);
  assert.match(rendered, /reportable/);
});

test('partitionFeedback keeps some references for the evaluator that it withholds from the author', () => {
  const refs = [
    artifact('train-1', { partition: 'train' }),
    artifact('heldout-1', { visibility: 'held-out', partition: 'held-out' }),
  ];
  assert.deepEqual(ok(partitionFeedback(refs, 'author')).visible.map((ref) => ref.id), ['train-1']);
  assert.deepEqual(ok(partitionFeedback(refs, 'evaluator')).visible.map((ref) => ref.id), ['train-1', 'heldout-1']);
});

test('a held-out reference is a privacy violation for the author and readable by the evaluator', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const ref = artifact('heldout-1', { content: 'held-out evidence', visibility: 'held-out', partition: 'held-out' });
  ok(store.put(ref, 'held-out evidence'));
  err(readArtifact(ref, 'author', 0, store), 'EFK_PRIVACY_VIOLATION', 'author');
  err(readArtifact(ref, 'asset-staging', 0, store), 'EFK_PRIVACY_VIOLATION', 'asset-staging');
  assert.equal(ok(readArtifact(ref, 'evaluator', 0, store)), 'held-out evidence');
});

test('a partition-only restriction is also a privacy violation for the author', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const ref = artifact('final-1', { content: 'final evidence', visibility: 'internal', partition: 'final' });
  ok(store.put(ref, 'final evidence'));
  err(readArtifact(ref, 'author', 0, store), 'EFK_PRIVACY_VIOLATION', 'author');
  assert.equal(ok(readArtifact(ref, 'evaluator', 0, store)), 'final evidence');
});

test/l2-artifact-binding.test.js:
/**
 * l2_artifact_port cp1 — attempt binding (S09): graph, node, attempt, epoch and base revision must
 * match, and a result computed against a superseded base is refused before it is committed.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';

import { createMemoryArtifactStore } from '../dist/storage/index.js';
import { admitArtifact, bindingMismatches, checkBinding } from '../dist/storage/artifacts/index.js';

const PROTOCOL = { namespace: 'evofence.runtime/1', schemaVersion: '1.1.0' };
const digestPort = {
  digest: (bytes) => `sha256:${createHash('sha256').update(bytes, 'utf8').digest('hex')}`,
};
const DIGEST = (seed) => digestPort.digest(String(seed));

const ok = (result, what) => {
  assert.equal(result.ok, true, `${what ?? 'call'} expected success, got ${JSON.stringify(result.error)}`);
  return result.value;
};
const err = (result, code, what) => {
  assert.equal(result.ok, false, `${what ?? 'call'} expected a typed rejection`);
  assert.equal(result.error.code, code, `${what ?? 'call'} rejected with ${result.error.code}`);
  return result.error;
};

const SCHEMA = { name: 'TaskEvidenceReport', version: '1.1.0', digest: DIGEST('schema') };

function binding(over = {}) {
  return {
    sessionId: 'session-1',
    hostSessionId: null,
    graph: { graphId: 'graph-1', revision: 7, digest: DIGEST('graph') },
    nodeId: 'node-1',
    attemptId: 'attempt-1',
    attemptOrdinal: 1,
    epoch: 3,
    baseDigest: DIGEST('base'),
    ...over,
  };
}

function artifact(id, over = {}) {
  const { content = id, ...rest } = over;
  return {
    protocol: PROTOCOL,
    id,
    digest: DIGEST(content),
    producer: { actorId: 'kernel-1', kind: 'kernel', identityRef: null },
    binding: binding(),
    schema: { ...SCHEMA },
    location: `artifact://${id}`,
    visibility: 'internal',
    expiresAt: null,
    partition: 'not-evaluation',
    ...rest,
  };
}

const nodeProduct = (optionOver = {}, bindingOver = {}) => ({
  productKind: 'node-product',
  schema: { ...SCHEMA },
  binding: binding(bindingOver),
  ...optionOver,
});

test('a reference bound to the consuming attempt passes and reports its binding', () => {
  const ref = artifact('art-1');
  const bound = ok(checkBinding(ref, nodeProduct()));
  assert.equal(bound.baseDigest, DIGEST('base'));
  assert.deepEqual(bindingMismatches(bound, binding()), []);
});

test('a node product with no binding at all is refused', () => {
  const ref = artifact('art-1', { binding: null });
  const failure = err(checkBinding(ref, nodeProduct()), 'EFK_ARTIFACT_BINDING_MISMATCH');
  assert.match(failure.message, /carries no attempt binding/);
});

test('every binding field is checked, and the refusal names the fields that disagree', () => {
  const cases = {
    'graph.graphId': { graph: { graphId: 'graph-2', revision: 7, digest: DIGEST('graph') } },
    'graph.revision': { graph: { graphId: 'graph-1', revision: 8, digest: DIGEST('graph') } },
    'graph.digest': { graph: { graphId: 'graph-1', revision: 7, digest: DIGEST('other-graph') } },
    nodeId: { nodeId: 'node-2' },
    attemptId: { attemptId: 'attempt-2' },
    attemptOrdinal: { attemptOrdinal: 2 },
    epoch: { epoch: 4 },
    baseDigest: { baseDigest: DIGEST('other-base') },
  };
  for (const [field, over] of Object.entries(cases)) {
    const ref = artifact('art-1', { binding: binding(over) });
    const failure = err(checkBinding(ref, nodeProduct()), 'EFK_ARTIFACT_BINDING_MISMATCH', field);
    assert.match(failure.message, new RegExp(field.replace('.', '\\.')), `${field} must be named`);
  }
});

test('a result computed against a superseded base is refused', () => {
  const ref = artifact('art-old-base', { binding: binding({ baseDigest: DIGEST('base-v1') }) });
  const failure = err(checkBinding(ref, nodeProduct({}, { baseDigest: DIGEST('base-v2') })), 'EFK_ARTIFACT_BINDING_MISMATCH');
  assert.match(failure.message, /baseDigest/);
});

test('the superseded-base result never reaches the store, so nothing is committed', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const stale = artifact('art-old-base', { content: 'stale-result', binding: binding({ baseDigest: DIGEST('base-v1') }) });
  err(admitArtifact({ ref: stale, bytes: 'stale-result', expectation: nodeProduct({}, { baseDigest: DIGEST('base-v2') }) }, store), 'EFK_ARTIFACT_BINDING_MISMATCH');
  assert.deepEqual(store.ids(), [], 'a refused submission must leave no artifact behind');

  const current = artifact('art-current', { content: 'current-result', binding: binding({ baseDigest: DIGEST('base-v2') }) });
  const stored = ok(admitArtifact({ ref: current, bytes: 'current-result', expectation: nodeProduct({}, { baseDigest: DIGEST('base-v2') }) }, store));
  assert.equal(stored.disposition, 'stored');
  assert.equal(ok(store.get(current)), 'current-result');
});

test('a pre-source snapshot may carry no binding and asserts nothing', () => {
  const ref = artifact('snapshot-1', { binding: null });
  const expectation = { productKind: 'pre-source', schema: { ...SCHEMA }, binding: null };
  assert.equal(checkBinding(ref, expectation).ok, true);
  assert.equal(ok(checkBinding(ref, expectation)), null);
});

test('a pre-source snapshot bound by a consuming command must match that binding', () => {
  const ref = artifact('snapshot-1', { binding: null });
  const expectation = { productKind: 'pre-source', schema: { ...SCHEMA }, binding: binding() };
  err(checkBinding(ref, expectation), 'EFK_ARTIFACT_BINDING_MISMATCH', 'unbound snapshot under a bound expectation');
  ok(checkBinding(artifact('snapshot-1'), expectation));
});

test('the declared schema version is checked on the writer path too', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const ref = artifact('art-1', { content: 'x', schema: { name: 'TaskEvidenceReport', version: '1.2.0', digest: DIGEST('schema') } });
  err(admitArtifact({ ref, bytes: 'x', expectation: nodeProduct() }, store), 'EFK_ARTIFACT_BINDING_MISMATCH', 'schema version');
  assert.deepEqual(store.ids(), []);
});

test/l2-artifact-consumers.test.js:
/**
 * l2_artifact_port cp3 — the single consumer entry (`verifyForConsumer`) for workspace, evaluator
 * and asset, and the frozen error matrix each of their failure paths produces.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';

import { createMemoryArtifactStore } from '../dist/storage/index.js';
import { ERROR_CODES } from '../dist/protocol/index.js';
import { ARTIFACT_ERROR_MATRIX, verifyForConsumer } from '../dist/storage/artifacts/index.js';

const PROTOCOL = { namespace: 'evofence.runtime/1', schemaVersion: '1.1.0' };
const digestPort = {
  digest: (bytes) => `sha256:${createHash('sha256').update(bytes, 'utf8').digest('hex')}`,
};
const DIGEST = (seed) => digestPort.digest(String(seed));

const ok = (result, what) => {
  assert.equal(result.ok, true, `${what ?? 'call'} expected success, got ${JSON.stringify(result.error)}`);
  return result.value;
};
const err = (result, code, what) => {
  assert.equal(result.ok, false, `${what ?? 'call'} expected a typed rejection`);
  assert.equal(result.error.code, code, `${what ?? 'call'} rejected with ${result.error.code}`);
  return result.error;
};

const SCHEMA = { name: 'TaskEvidenceReport', version: '1.1.0', digest: DIGEST('schema') };

function binding(over = {}) {
  return {
    sessionId: 'session-1',
    hostSessionId: null,
    graph: { graphId: 'graph-1', revision: 7, digest: DIGEST('graph') },
    nodeId: 'node-1',
    attemptId: 'attempt-1',
    attemptOrdinal: 1,
    epoch: 3,
    baseDigest: DIGEST('base'),
    ...over,
  };
}

function artifact(id, over = {}) {
  const { content = id, ...rest } = over;
  return {
    protocol: PROTOCOL,
    id,
    digest: DIGEST(content),
    producer: { actorId: 'kernel-1', kind: 'kernel', identityRef: null },
    binding: binding(),
    schema: { ...SCHEMA },
    location: `artifact://${id}`,
    visibility: 'internal',
    expiresAt: null,
    partition: 'not-evaluation',
    ...rest,
  };
}

const nodeProduct = (bindingOver = {}) => ({ productKind: 'node-product', schema: { ...SCHEMA }, binding: binding(bindingOver) });

function storeWith(refs) {
  const store = createMemoryArtifactStore({ digest: digestPort });
  for (const [ref, bytes] of refs) {
    const stored = store.put(ref, bytes);
    assert.equal(stored.ok, true, `fixture ${ref.id} must store: ${JSON.stringify(stored.error)}`);
  }
  return store;
}

test('the workspace consumer admits a bound attempt artifact and receives its bytes', () => {
  const ref = artifact('art-1', { content: 'diff-bytes' });
  const admission = ok(verifyForConsumer({ role: 'workspace', refs: [ref], expectation: nodeProduct(), at: 0 }, storeWith([[ref, 'diff-bytes']])));
  assert.equal(admission.role, 'workspace');
  assert.equal(admission.audience, 'author');
  assert.deepEqual(admission.evidence, [{ ref, bytes: 'diff-bytes' }]);
});

test('the workspace consumer refuses a result bound to a superseded base instead of admitting it', () => {
  const ref = artifact('art-1', { content: 'stale', binding: binding({ baseDigest: DIGEST('base-v1') }) });
  err(
    verifyForConsumer({ role: 'workspace', refs: [ref], expectation: nodeProduct({ baseDigest: DIGEST('base-v2') }), at: 0 }, storeWith([[ref, 'stale']])),
    'EFK_ARTIFACT_BINDING_MISMATCH',
  );
});

test('the workspace consumer cannot read held-out evidence', () => {
  const ref = artifact('heldout-1', { content: 'held-out', visibility: 'held-out', partition: 'held-out' });
  err(
    verifyForConsumer({ role: 'workspace', refs: [ref], expectation: nodeProduct(), at: 0 }, storeWith([[ref, 'held-out']])),
    'EFK_PRIVACY_VIOLATION',
  );
});

test('the evaluator consumer reads held-out evidence, which is its subject matter', () => {
  const ref = artifact('heldout-1', { content: 'held-out', visibility: 'held-out', partition: 'held-out' });
  const admission = ok(
    verifyForConsumer({ role: 'evaluator', refs: [ref], expectation: nodeProduct(), at: 0 }, storeWith([[ref, 'held-out']])),
  );
  assert.equal(admission.audience, 'evaluator');
  assert.equal(admission.evidence[0].bytes, 'held-out');
});

test('the evaluator consumer refuses an artifact whose schema is not the expected version', () => {
  const ref = artifact('art-1', { content: 'evidence', schema: { name: 'TaskEvidenceReport', version: '1.2.0', digest: DIGEST('schema') } });
  err(
    verifyForConsumer({ role: 'evaluator', refs: [ref], expectation: nodeProduct(), at: 0 }, storeWith([[ref, 'evidence']])),
    'EFK_ARTIFACT_BINDING_MISMATCH',
  );
});

test('the asset consumer admits train source traces and content references with their bytes', () => {
  const content = artifact('asset-content', { content: 'skill', partition: 'train' });
  const trace = artifact('asset-trace', { content: 'trace', partition: 'train' });
  const admission = ok(
    verifyForConsumer(
      { role: 'asset', contentRefs: [content], sourceTraces: [trace], revokedDependencies: [], at: 0 },
      storeWith([[content, 'skill'], [trace, 'trace']]),
    ),
  );
  assert.equal(admission.audience, 'asset-staging');
  assert.deepEqual(admission.evidence.map((item) => item.bytes), ['skill', 'trace']);
});

test('an asset source trace that is not from train is an evaluation protocol mismatch', () => {
  const content = artifact('asset-content', { partition: 'train' });
  const trace = artifact('dev-trace', { content: 'trace', partition: 'dev' });
  err(
    verifyForConsumer({ role: 'asset', contentRefs: [content], sourceTraces: [trace], revokedDependencies: [], at: 0 }, storeWith([[content, content.id], [trace, 'trace']])),
    'EFK_EVALUATION_PROTOCOL_MISMATCH',
  );
});

test('asset content from held-out or final never becomes asset material', () => {
  const trace = artifact('train-trace', { partition: 'train' });
  for (const partition of ['held-out', 'final']) {
    const ref = artifact(`content-${partition}`, { content: 'x', partition });
    err(
      verifyForConsumer({ role: 'asset', contentRefs: [ref], sourceTraces: [trace], revokedDependencies: [], at: 0 }, storeWith([[ref, 'x']])),
      'EFK_EVALUATION_PROTOCOL_MISMATCH',
      partition,
    );
  }
});

test('private asset material is a privacy violation for the asset-staging audience', () => {
  const trace = artifact('train-trace', { partition: 'train' });
  const ref = artifact('private-content', { content: 'secret', visibility: 'private', partition: 'train' });
  err(
    verifyForConsumer({ role: 'asset', contentRefs: [ref], sourceTraces: [trace], revokedDependencies: [], at: 0 }, storeWith([[ref, 'secret']])),
    'EFK_PRIVACY_VIOLATION',
  );
});

test('a revoked dependency invalidates the asset qualification', () => {
  const content = artifact('asset-content', { content: 'skill', partition: 'train' });
  const trace = artifact('asset-trace', { content: 'trace', partition: 'train' });
  const failure = err(
    verifyForConsumer(
      { role: 'asset', contentRefs: [content], sourceTraces: [trace], revokedDependencies: ['dep-1'], at: 0 },
      storeWith([[content, 'skill'], [trace, 'trace']]),
    ),
    'EFK_ASSET_QUALIFICATION_INVALID',
  );
  assert.deepEqual(failure.refs, ['dep-1']);
});

test('an expired reference is unavailable to every consumer', () => {
  const ref = artifact('expired-1', { content: 'evidence', expiresAt: 10 });
  err(
    verifyForConsumer({ role: 'evaluator', refs: [ref], expectation: nodeProduct(), at: 10 }, storeWith([[ref, 'evidence']])),
    'EFK_ARTIFACT_UNAVAILABLE',
  );
});

test('the error matrix names only frozen codes and covers every code this lane can return', () => {
  const reported = Object.keys(ARTIFACT_ERROR_MATRIX);
  for (const code of reported) {
    assert.equal(ERROR_CODES.includes(code), true, `${code} is not a frozen ErrorCode`);
    assert.equal(ARTIFACT_ERROR_MATRIX[code].length > 0, true, `${code} has no documented trigger`);
  }
  assert.deepEqual(reported.sort(), [
    'EFK_ARTIFACT_BINDING_MISMATCH',
    'EFK_ARTIFACT_DIGEST_MISMATCH',
    'EFK_ARTIFACT_UNAVAILABLE',
    'EFK_ASSET_QUALIFICATION_INVALID',
    'EFK_EVALUATION_PROTOCOL_MISMATCH',
    'EFK_PRIVACY_VIOLATION',
    'EFK_SCHEMA_INVALID',
  ]);
});

test/l2-artifact-identity.test.js:
/**
 * l2_artifact_port cp1 — producer attribution, the expected schema version, and the read path that
 * never substitutes a reference summary for content.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';

import { createMemoryArtifactStore } from '../dist/storage/index.js';
import { admitArtifact, attributeProducer, checkAvailability, matchSchema, readArtifact } from '../dist/storage/artifacts/index.js';

const PROTOCOL = { namespace: 'evofence.runtime/1', schemaVersion: '1.1.0' };
const digestPort = {
  digest: (bytes) => `sha256:${createHash('sha256').update(bytes, 'utf8').digest('hex')}`,
};
const DIGEST = (seed) => digestPort.digest(String(seed));

const ok = (result, what) => {
  assert.equal(result.ok, true, `${what ?? 'call'} expected success, got ${JSON.stringify(result.error)}`);
  return result.value;
};
const err = (result, code, what) => {
  assert.equal(result.ok, false, `${what ?? 'call'} expected a typed rejection`);
  assert.equal(result.error.code, code, `${what ?? 'call'} rejected with ${result.error.code}`);
  return result.error;
};

const SCHEMA = { name: 'TaskEvidenceReport', version: '1.1.0', digest: DIGEST('schema') };

function artifact(id, over = {}) {
  const { content = id, ...rest } = over;
  return {
    protocol: PROTOCOL,
    id,
    digest: DIGEST(content),
    producer: { actorId: 'kernel-1', kind: 'kernel', identityRef: null },
    binding: null,
    schema: { ...SCHEMA },
    location: `artifact://${id}`,
    visibility: 'internal',
    expiresAt: null,
    partition: 'not-evaluation',
    ...rest,
  };
}

function spyStore() {
  const calls = [];
  return {
    calls,
    put: (ref, bytes) => {
      calls.push(['put', ref.id, bytes]);
      return { ok: true, value: { disposition: 'stored' } };
    },
    get: (ref) => {
      calls.push(['get', ref.id]);
      throw new Error('the store must not be consulted for a withheld reference');
    },
    ids: () => [],
  };
}

test('a kernel producer is attributable and returned unchanged', () => {
  const ref = artifact('art-1');
  assert.deepEqual(ok(attributeProducer(ref)), ref.producer);
});

test('a human producer with no verified identity reference cannot be attributed', () => {
  const ref = artifact('art-1', { producer: { actorId: 'human-1', kind: 'human', identityRef: null } });
  err(attributeProducer(ref), 'EFK_ARTIFACT_BINDING_MISMATCH', 'unattributable human producer');
});

test('a human producer carrying a verified identity reference is attributable', () => {
  const identity = artifact('identity-1');
  const ref = artifact('art-1', { producer: { actorId: 'human-1', kind: 'human', identityRef: identity } });
  assert.equal(ok(attributeProducer(ref)).actorId, 'human-1');
});

test('the declared schema triple must match the expected name, version and digest', () => {
  const ref = artifact('art-1');
  assert.equal(ok(matchSchema(ref, { ...SCHEMA })).version, '1.1.0');
  err(matchSchema(ref, { ...SCHEMA, name: 'OtherReport' }), 'EFK_ARTIFACT_BINDING_MISMATCH', 'name');
  err(matchSchema(ref, { ...SCHEMA, version: '1.2.0' }), 'EFK_ARTIFACT_BINDING_MISMATCH', 'version');
  err(matchSchema(ref, { ...SCHEMA, digest: DIGEST('other-schema') }), 'EFK_ARTIFACT_BINDING_MISMATCH', 'digest');
});

test('readArtifact resolves the real bytes through the injected store', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const ref = artifact('art-1', { content: 'evidence-bytes' });
  ok(store.put(ref, 'evidence-bytes'));
  assert.equal(ok(readArtifact(ref, 'author', 0, store)), 'evidence-bytes');
});

test('a reference whose content is not stored is unavailable, never answered from its own summary', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const ref = artifact('art-missing');
  const failure = err(readArtifact(ref, 'author', 0, store), 'EFK_ARTIFACT_UNAVAILABLE');
  assert.match(failure.message, /art-missing/);
});

test('an expired reference is unavailable even while the store still holds its bytes', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const ref = artifact('art-1', { content: 'evidence-bytes', expiresAt: 1000 });
  ok(store.put(ref, 'evidence-bytes'));
  assert.equal(ok(checkAvailability(ref, 999)).id, 'art-1');
  err(checkAvailability(ref, 1000), 'EFK_ARTIFACT_UNAVAILABLE', 'exact expiry instant is expired');
  err(readArtifact(ref, 'author', 5000, store), 'EFK_ARTIFACT_UNAVAILABLE', 'expired read');
});

test('a withheld reference is refused before the store is consulted', () => {
  const store = spyStore();
  const ref = artifact('art-heldout', { visibility: 'held-out', partition: 'held-out' });
  err(readArtifact(ref, 'author', 0, store), 'EFK_PRIVACY_VIOLATION', 'author reading held-out');
  assert.deepEqual(store.calls, []);
});

test('the store boundary refusals propagate unchanged: digest mismatch and a malformed reference', () => {
  const store = createMemoryArtifactStore({ digest: digestPort });
  const ref = artifact('art-1', { content: 'declared-bytes' });
  const expectation = { productKind: 'pre-source', schema: { ...SCHEMA }, binding: null };
  err(admitArtifact({ ref, bytes: 'tampered-bytes', expectation }, store), 'EFK_ARTIFACT_DIGEST_MISMATCH', 'bytes vs digest');
  err(admitArtifact({ ref: { ...ref, extra: true }, bytes: 'declared-bytes', expectation }, store), 'EFK_SCHEMA_INVALID', 'malformed ref');
  assert.deepEqual(store.ids(), []);
});

test/l2-artifact-repairs.test.js:
/** Regression evidence for review M1-M4 and N1-N3; every test is flat. */
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { createMemoryArtifactStore } from '../dist/storage/index.js';
import { decode } from '../dist/protocol/index.js';
import {
  admitArtifact, bindingMismatches, checkBinding, defaultReportRefs, isRestrictedPartition,
  partitionFeedback, readArtifact, verifyForConsumer, withheldReason,
} from '../dist/storage/artifacts/index.js';

const digestPort = { digest: (bytes) => `sha256:${createHash('sha256').update(bytes).digest('hex')}` };
const digest = (seed) => digestPort.digest(seed);
const schema = { name: 'TaskEvidenceReport', version: '1.1.0', digest: digest('schema') };
const binding = (over = {}) => ({
  sessionId: 'session-1', hostSessionId: null,
  graph: { graphId: 'graph-1', revision: 7, digest: digest('graph') },
  nodeId: 'node-1', attemptId: 'attempt-1', attemptOrdinal: 1, epoch: 3,
  baseDigest: digest('base'), ...over,
});
const expectation = (over = {}) => ({ productKind: 'node-product', schema, binding: binding(over) });
const artifact = (id, over = {}) => ({
  protocol: { namespace: 'evofence.runtime/1', schemaVersion: '1.1.0' },
  id, digest: digest(id), producer: { actorId: 'kernel-1', kind: 'kernel', identityRef: null },
  binding: binding(), schema, location: `artifact://${id}`, visibility: 'internal',
  expiresAt: null, partition: 'train', ...over,
});
const ok = (result) => {
  assert.equal(result.ok, true, JSON.stringify(result.error));
  return result.value;
};
const err = (result, code) => {
  assert.equal(result.ok, false, 'expected typed rejection');
  assert.equal(result.error.code, code);
  return result.error;
};
function storeWith(refs = []) {
  const store = createMemoryArtifactStore({ digest: digestPort });
  for (const ref of refs) ok(store.put(ref, ref.id));
  return store;
}
function noReads() {
  const calls = [];
  return {
    calls, ids: () => [],
    put: () => { throw new Error('rejected material must not be written'); },
    get: (ref) => { calls.push(ref.id); throw new Error('rejected material must not be read'); },
  };
}
const assetRequest = (contentRefs, sourceTraces, revokedDependencies = []) => ({
  role: 'asset', contentRefs, sourceTraces, revokedDependencies, at: 0,
});

test('M1: stale binding rejection is independent of missing or stored bytes for both bound consumers', () => {
  const ref = artifact('stale-result', { binding: binding({ baseDigest: digest('old-base') }) });
  for (const role of ['workspace', 'evaluator']) {
    const request = { role, refs: [ref], expectation: expectation(), at: 0 };
    const absent = err(verifyForConsumer(request, storeWith()), 'EFK_ARTIFACT_BINDING_MISMATCH');
    const present = err(verifyForConsumer(request, storeWith([ref])), 'EFK_ARTIFACT_BINDING_MISMATCH');
    assert.deepEqual(absent, present);
    const spy = noReads();
    err(verifyForConsumer(request, spy), 'EFK_ARTIFACT_BINDING_MISMATCH');
    assert.deepEqual(spy.calls, []);
  }
});

test('M1: producer and every schema axis reject before retrieving bytes for both bound consumers', () => {
  const badRefs = [
    artifact('bad-producer', { producer: { actorId: 'human-1', kind: 'human', identityRef: null } }),
    ...[
      { name: 'OtherReport' }, { version: '1.2.0' }, { digest: digest('other-schema') },
    ].map((over, index) => artifact(`bad-schema-${index}`, { schema: { ...schema, ...over } })),
  ];
  for (const role of ['workspace', 'evaluator']) {
    for (const ref of badRefs) {
      const request = { role, refs: [ref], expectation: expectation(), at: 0 };
      const absent = err(verifyForConsumer(request, storeWith()), 'EFK_ARTIFACT_BINDING_MISMATCH');
      assert.deepEqual(err(verifyForConsumer(request, storeWith([ref])), 'EFK_ARTIFACT_BINDING_MISMATCH'), absent);
      const spy = noReads();
      err(verifyForConsumer(request, spy), 'EFK_ARTIFACT_BINDING_MISMATCH');
      assert.deepEqual(spy.calls, []);
    }
  }
});

test('M1: privacy still precedes expiry, producer, schema and binding refusal', () => {
  const ref = artifact('withheld-stale', {
    visibility: 'held-out', partition: 'held-out', expiresAt: 0,
    binding: binding({ baseDigest: digest('old-base') }),
    schema: { ...schema, version: '1.2.0' },
    producer: { actorId: 'human-1', kind: 'human', identityRef: null },
  });
  const spy = noReads();
  err(verifyForConsumer({ role: 'workspace', refs: [ref], expectation: expectation(), at: 0 }, spy), 'EFK_PRIVACY_VIOLATION');
  assert.deepEqual(spy.calls, []);
});

test('M2: revoked qualification rejects before any material read regardless of store state', () => {
  const content = artifact('asset-content');
  const trace = artifact('asset-trace');
  const request = assetRequest([content], [trace], ['revoked-dep']);
  const absent = err(verifyForConsumer(request, storeWith()), 'EFK_ASSET_QUALIFICATION_INVALID');
  assert.deepEqual(err(verifyForConsumer(request, storeWith([content, trace])), 'EFK_ASSET_QUALIFICATION_INVALID'), absent);
  const spy = noReads();
  err(verifyForConsumer(request, spy), 'EFK_ASSET_QUALIFICATION_INVALID');
  const forbidden = artifact('forbidden', { visibility: 'final', partition: 'final', expiresAt: 0 });
  err(verifyForConsumer(assetRequest([forbidden], [forbidden], ['revoked-dep']), spy), 'EFK_ASSET_QUALIFICATION_INVALID');
  err(verifyForConsumer(assetRequest([], [], ['revoked-dep']), spy), 'EFK_ASSET_QUALIFICATION_INVALID');
  assert.deepEqual(spy.calls, []);
});

test('M3: unknown visibility and partition enums are typed failures at report and classification entries', () => {
  const badEnums = [
    { visibility: 'secret-tier' }, { partition: 'holdout' },
    { visibility: '__proto__' }, { partition: 'constructor' },
    { visibility: 'toString', partition: '__proto__' },
    { visibility: 'private', partition: 'holdout' },
  ];
  for (const over of badEnums) {
    const ref = artifact('malformed', over);
    err(defaultReportRefs([artifact('reportable'), ref]), 'EFK_SCHEMA_INVALID');
    for (const audience of ['author', 'evaluator', 'report', 'asset-staging']) {
      err(partitionFeedback([artifact('reportable'), ref], audience), 'EFK_SCHEMA_INVALID');
      err(withheldReason(ref, audience), 'EFK_SCHEMA_INVALID');
    }
    err(isRestrictedPartition(ref), 'EFK_SCHEMA_INVALID');
    assert.equal('value' in defaultReportRefs([ref]), false, 'a refused report exposes no partial partition');
  }
});

test('M3: malformed enums reject without relying on a store codec in direct and consumer reads', () => {
  for (const over of [{ visibility: 'secret-tier' }, { partition: 'holdout' }]) {
    const ref = artifact('malformed', over);
    const spy = noReads();
    for (const audience of ['author', 'evaluator', 'report', 'asset-staging']) {
      err(readArtifact(ref, audience, 0, spy), 'EFK_SCHEMA_INVALID');
    }
    for (const role of ['workspace', 'evaluator']) {
      err(verifyForConsumer({ role, refs: [ref], expectation: expectation(), at: 0 }, spy), 'EFK_SCHEMA_INVALID');
    }
    err(verifyForConsumer(assetRequest([ref], [artifact('trace')]), spy), 'EFK_SCHEMA_INVALID');
    assert.deepEqual(spy.calls, []);
    const content = artifact('content');
    err(verifyForConsumer(assetRequest([content], [ref]), storeWith([content])), 'EFK_SCHEMA_INVALID');
  }
});

test('M4: either empty material list and both empty lists reject before any asset read', () => {
  const content = artifact('content');
  const trace = artifact('trace');
  for (const [contents, traces] of [[[], []], [[], [trace]], [[content], []]]) {
    const spy = noReads();
    const request = assetRequest(contents, traces);
    const absent = err(verifyForConsumer(request, storeWith()), 'EFK_SCHEMA_INVALID');
    assert.deepEqual(err(verifyForConsumer(request, storeWith([content, trace])), 'EFK_SCHEMA_INVALID'), absent);
    err(verifyForConsumer(request, spy), 'EFK_SCHEMA_INVALID');
    assert.deepEqual(spy.calls, []);
  }
  assert.equal(ok(verifyForConsumer(assetRequest([content], [trace]), storeWith([content, trace]))).evidence.length, 2);
});

test('N1: exact expiry refuses before bytes and before consumer binding, while null never expires', () => {
  const ref = artifact('expires-now', { expiresAt: 10 });
  const store = storeWith([ref]);
  assert.equal(ok(readArtifact(ref, 'author', 9, store)), ref.id);
  const spy = noReads();
  err(readArtifact(ref, 'author', 10, spy), 'EFK_ARTIFACT_UNAVAILABLE');
  for (const role of ['workspace', 'evaluator']) {
    err(verifyForConsumer({ role, refs: [ref], expectation: expectation({ baseDigest: digest('different') }), at: 10 }, spy), 'EFK_ARTIFACT_UNAVAILABLE');
  }
  assert.deepEqual(spy.calls, []);
  const timeless = artifact('no-expiry');
  assert.equal(ok(readArtifact(timeless, 'author', Number.MAX_SAFE_INTEGER, storeWith([timeless]))), timeless.id);
});

test('N2: kernel and host sessions must match on writer and bound consumer paths', () => {
  for (const over of [{ sessionId: 'session-2' }, { hostSessionId: 'host-2' }]) {
    const ref = artifact('different-session', { binding: binding(over) });
    ok(decode('Binding', ref.binding));
    assert.deepEqual(bindingMismatches(ref.binding, binding()), Object.keys(over));
    err(checkBinding(ref, expectation()), 'EFK_ARTIFACT_BINDING_MISMATCH');
    const spy = noReads();
    err(admitArtifact({ ref, bytes: ref.id, expectation: expectation() }, spy), 'EFK_ARTIFACT_BINDING_MISMATCH');
    for (const role of ['workspace', 'evaluator']) {
      err(verifyForConsumer({ role, refs: [ref], expectation: expectation(), at: 0 }, spy), 'EFK_ARTIFACT_BINDING_MISMATCH');
    }
    assert.deepEqual(spy.calls, []);
  }
});

test('N2: hostSessionId preserves frozen null and string semantics in both directions', () => {
  for (const hostSessionId of [null, 'host-1']) {
    const ref = artifact('session-bound', { binding: binding({ hostSessionId }) });
    ok(decode('Binding', ref.binding));
    ok(checkBinding(ref, expectation({ hostSessionId })));
    const other = hostSessionId === null ? 'host-1' : null;
    err(checkBinding(ref, expectation({ hostSessionId: other })), 'EFK_ARTIFACT_BINDING_MISMATCH');
    const sourceExpectation = { ...expectation({ hostSessionId: other }), productKind: 'pre-source' };
    err(checkBinding(ref, sourceExpectation), 'EFK_ARTIFACT_BINDING_MISMATCH');
  }
});

test('N3: privacy refusals contain no withheld id, locator or digest for any restricted audience', () => {
  for (const over of [{ visibility: 'private' }, { visibility: 'held-out' }, { partition: 'held-out' }, { partition: 'final' }]) {
    const ref = artifact('withheld-identity-42', over);
    const spy = noReads();
    const refusals = ['author', 'report', 'asset-staging'].map((audience) => readArtifact(ref, audience, 0, spy));
    refusals.push(verifyForConsumer({ role: 'workspace', refs: [ref], expectation: expectation(), at: 0 }, spy));
    for (const refusal of refusals) {
      const failure = err(refusal, 'EFK_PRIVACY_VIOLATION');
      assert.deepEqual(failure.refs, []);
      const rendered = JSON.stringify(refusal);
      for (const forbidden of [ref.id, ref.location, ref.digest]) assert.equal(rendered.includes(forbidden), false);
    }
    assert.deepEqual(spy.calls, []);
  }
});

test('N3: asset protocol refusals contain no restricted material identity in message or refs', () => {
  for (const partition of ['held-out', 'final']) {
    const ref = artifact('restricted-identity-42', { partition });
    const content = artifact('content');
    const trace = artifact('trace');
    const refusals = [
      verifyForConsumer(assetRequest([ref], [trace]), noReads()),
      verifyForConsumer(assetRequest([content], [ref]), storeWith([content])),
    ];
    for (const refusal of refusals) {
      const failure = err(refusal, 'EFK_EVALUATION_PROTOCOL_MISMATCH');
      assert.deepEqual(failure.refs, []);
      for (const forbidden of [ref.id, ref.location, ref.digest]) assert.equal(JSON.stringify(refusal).includes(forbidden), false);
    }
  }
});
